private TreeNode<T> rotateRight(TreeNode<T> node){
    // If the node is null or it has no left child, nothing to rotate
    if (node == null || node.left == null) {
        return node;
    }
    // The current left child becomes the new root after rotation
    TreeNode<T> newRoot = node.left;

    // Transfer the right subtree of newRoot to become the left subtree of node
    node.left = newRoot.right;
    if (newRoot.right != null) {
        newRoot.right.parent = node;
    }

    // Attach node as the right child of newRoot
    newRoot.right = node;

    // Update parent links (if the tree tracks them)
    newRoot.parent = node.parent;
    node.parent = newRoot;

    // Return the new root of this subtree
    return newRoot;
}

