private int parseEndOfLine(String headerPart, int end) {
    int len = headerPart.length();
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null || headerPart.isEmpty()){
        return -1;
    }
    // Ensure the search starts from the current end index
    int length = headerPart.length();
    for(int i = end; i + 1 < length; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1; // \r\n sequence not found
}

private int parseEndOfLine(String headerPart,int end){
    // Scan for the CRLF sequence starting at the given end index
    int length = headerPart.length();
    for (int i = end; i < length - 1; i++){
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            // Return the index of the CR that starts the CRLF pair
            return i;
        }
    }
    // If no CRLF found, return -1 to indicate failure
    return -1;
}

