private int parseEndOfLine(String headerPart, int end) {
    int len = headerPart.length();
    while (end < len - 1) {
        if (headerPart.charAt(end) == '\r' && headerPart.charAt(end + 1) == '\n') {
            return end; // End of line detected at CR (followed by LF)
        }
        end++;
    }
    return end; // No CRLF found; return current index
}

