public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    java.util.Map<V, V> vertexMap = new java.util.HashMap<>();
    for (V v : graph.vertexSet()){
        vertexMap.put(v, v);
    }
    java.util.Map<E, E> edgeMap = new java.util.HashMap<>();
    for (E e : graph.edgeSet()){
        edgeMap.put(e, e);
    }
    return new IsomorphicGraphMapping<>(graph, graph, vertexMap, edgeMap);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    java.util.Map<V,V> vertexMap = new java.util.HashMap<>();
    java.util.Map<E,E> edgeMap = new java.util.HashMap<>();
    for (V v : graph.getVertices()){
        vertexMap.put(v, v);
    }
    for (E e : graph.getEdges()){
        edgeMap.put(e, e);
    }
    return new IsomorphicGraphMapping<>(graph, vertexMap, edgeMap);
}

