public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    registerDeleteOnExit(file);
}

private static void registerDeleteOnExit(File f) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children != null) {
            for (File child : children) {
                registerDeleteOnExit(child);
            }
        } else {
            throw new IOException("Failed to list contents of directory: " + f);
        }
    }
    // Register the file or directory to be deleted on JVM exit.
    f.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) throw new NullPointerException("File must not be null");
    final java.util.List<java.io.File> toDelete = new java.util.ArrayList<>();
    try {
        java.util.Deque<java.io.File> stack = new java.util.ArrayDeque<>();
        stack.push(file);
        while (!stack.isEmpty()) {
            java.io.File current = stack.pop();
            if (current.isDirectory()) {
                java.io.File[] children = current.listFiles();
                if (children != null) {
                    for (java.io.File child : children) {
                        stack.push(child);
                    }
                }
            }
            toDelete.add(current);
        }
    } catch (SecurityException se) {
        throw new IOException("Unable to access file: " + file, se);
    }
    java.lang.Runtime.getRuntime().addShutdownHook(new java.lang.Thread(() -> {
        for (int i = toDelete.size() - 1; i >= 0; i--) {
            java.io.File f = toDelete.get(i);
            try {
                f.delete();
            } catch (Throwable ignored) {}
        }
    }));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file.getAbsolutePath());
    }

    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }

    // Schedule the file or directory for deletion on JVM exit
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            deleteRecursively(file);
        } catch (IOException e) {
            // Cannot throw checked exception from a shutdown hook; rethrow as unchecked
            throw new RuntimeException(e);
        }
    }));
}

private static void deleteRecursively(File f) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursively(child);
            }
        }
    }
    if (!f.delete()) {
        if (f.exists()) {
            throw new IOException("Failed to delete: " + f);
        }
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        // Nothing to schedule if the file does not exist
        return;
    }

    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                // Recursively schedule deletion for each child
                forceDeleteOnExit(child);
            }
        }
    }

    // Schedule deletion of the file or directory itself
    file.deleteOnExit();
}

