public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Determine the size of the serialized message
    int size = schema.getMessageSize(message);
    // Preserve the original size for the return value
    int sizeForReturn = size;

    // Write the size as a Protobuf varint to the output stream
    while ((size & ~0x7F) != 0) {
        out.write((size & 0x7F) | 0x80);
        size >>>= 7;
    }
    out.write(size);

    // Write the actual message contents to the output stream
    schema.writeTo(out, message);

    // Return the original size
    return sizeForReturn;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Determine the serialized size of the message
    int rawSize = schema.getSerializedSize(message);
    // Create a CodedOutputStream to write to the provided OutputStream
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    // Write the size as a varint prefix
    codedOut.writeRawVarint32(rawSize);
    // Write the actual message using the schema and buffer
    schema.writeTo(codedOut, message, buffer);
    // Flush the stream to ensure all data is written
    codedOut.flush();
    // Return the size of the serialized message
    return rawSize;
}

