protected void subAppend(LoggingEvent event) {
    try {
        if (myWriter != null) {
            // Write the formatted event to the writer
            myWriter.write(layout.format(event));

            // If the layout does not ignore throwable information, write the throwable stack trace
            if (!layout.ignoresThrowable()) {
                Throwable t = event.getThrowableInformation() != null
                        ? event.getThrowableInformation().getThrowable()
                        : null;
                if (t != null) {
                    // Write the throwable's stack trace line by line
                    java.io.PrintWriter pw = new java.io.PrintWriter(myWriter);
                    t.printStackTrace(pw);
                    pw.flush();
                }
            }

            // Flush the writer if it supports flushing
            if (myWriter instanceof java.io.Flushable) {
                ((java.io.Flushable) myWriter).flush();
            }
        }
    } catch (java.io.IOException ioe) {
        if (errorHandler != null) {
            errorHandler.error("Error writing logging event to writer.", ioe, org.apache.log4j.spi.ErrorCode.WRITE_FAILURE);
        }
    } catch (Exception ex) {
        if (errorHandler != null) {
            errorHandler.error("Unexpected error while writing logging event.", ex, org.apache.log4j.spi.ErrorCode.WRITE_FAILURE);
        }
    }
}

