public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Class<?> rawType = (Class<?>) pt.getRawType();
    Type[] genericArgs = pt.getActualTypeArguments();

    Map<TypeVariable<?>, Type> varMap = new HashMap<>();
    if (!populateTypeVariableMap(targetType, rawType, varMap)) {
        return null;
    }

    Class<?>[] result = new Class<?>[genericArgs.length];
    for (int i = 0; i < genericArgs.length; i++) {
        Type t = genericArgs[i];
        while (t instanceof TypeVariable<?>) {
            TypeVariable<?> tv = (TypeVariable<?>) t;
            Type resolved = varMap.get(tv);
            if (resolved == null) {
                return null; // cannot resolve
            }
            t = resolved;
        }
        Class<?> clazz = toClass(t);
        if (clazz == null) {
            return null;
        }
        result[i] = clazz;
    }
    return result;
}

// Recursively search the target class hierarchy to build a map from type variables to concrete types.
private static boolean populateTypeVariableMap(Class<?> current, Class<?> targetRaw,
                                               Map<TypeVariable<?>, Type> map) {
    if (current == null) {
        return false;
    }
    // Check superclass
    Type superType = current.getGenericSuperclass();
    if (superType != null && tryResolve(superType, targetRaw, map)) {
        return true;
    }
    // Check interfaces
    for (Type iface : current.getGenericInterfaces()) {
        if (tryResolve(iface, targetRaw, map)) {
            return true;
        }
    }
    // Recurse up
    return populateTypeVariableMap(current.getSuperclass(), targetRaw, map);
}

private static boolean tryResolve(Type type, Class<?> targetRaw,
                                  Map<TypeVariable<?>, Type> map) {
    if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        Class<?> raw = (Class<?>) pt.getRawType();
        if (raw.equals(targetRaw)) {
            // Map the type variables of raw to the actual type arguments
            TypeVariable<?>[] vars = raw.getTypeParameters();
            Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
            return true;
        }
        // Continue searching in the raw class's hierarchy
        if (populateTypeVariableMap(raw, targetRaw, map)) {
            // Also map variables that appear in this parameterized type
            TypeVariable<?>[] vars = raw.getTypeParameters();
            Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
            return true;
        }
    } else if (type instanceof Class) {
        Class<?> cls = (Class<?>) type;
        if (cls.equals(targetRaw)) {
            return true;
        }
        if (populateTypeVariableMap(cls, targetRaw, map)) {
            return true;
        }
    }
    return false;
}

private static Class<?> toClass(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof GenericArrayType) {
        Type comp = ((GenericArrayType) type).getGenericComponentType();
        Class<?> compClass = toClass(comp);
        if (compClass != null) {
            return java.lang.reflect.Array.newInstance(compClass, 0).getClass();
        }
    }
    // WildcardType, TypeVariable, and others cannot be resolved to a concrete Class
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof java.lang.reflect.ParameterizedType)) {
        return null;
    }
    java.lang.reflect.ParameterizedType pt = (java.lang.reflect.ParameterizedType) genericType;
    java.lang.reflect.Type[] typeArgs = pt.getActualTypeArguments();
    // We only support concrete class arguments.
    java.util.List<Class<?>> classes = new java.util.ArrayList<>(typeArgs.length);
    for (java.lang.reflect.Type arg : typeArgs) {
        if (arg instanceof Class<?>) {
            classes.add((Class<?>) arg);
        } else if (arg instanceof java.lang.reflect.ParameterizedType) {
            // Use the raw type as the representative class.
            java.lang.reflect.Type raw = ((java.lang.reflect.ParameterizedType) arg).getRawType();
            if (raw instanceof Class<?>) {
                classes.add((Class<?>) raw);
            } else {
                return null;
            }
        } else if (arg instanceof java.lang.reflect.GenericArrayType) {
            // Resolve array component type.
            java.lang.reflect.Type comp = ((java.lang.reflect.GenericArrayType) arg).getGenericComponentType();
            if (comp instanceof Class<?>) {
                try {
                    classes.add(java.lang.reflect.Array.newInstance((Class<?>) comp, 0).getClass());
                } catch (Exception e) {
                    return null;
                }
            } else {
                return null;
            }
        } else {
            // Wildcard, type variable or other unresolved type.
            return null;
        }
    }
    return classes.toArray(new Class<?>[0]);
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] typeArgs = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        Type t = typeArgs[i];
        if (t instanceof Class) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof GenericArrayType) {
            Type comp = ((GenericArrayType) t).getGenericComponentType();
            if (comp instanceof Class) {
                result[i] = java.lang.reflect.Array.newInstance((Class<?>) comp, 0).getClass();
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType genericParam = (ParameterizedType) genericType;
    Type rawType = genericParam.getRawType();
    if (!(rawType instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) rawType;
    ParameterizedType targetParam = findParameterizedType(targetType, rawClass);
    if (targetParam == null) {
        return null;
    }
    Map<TypeVariable<?>, Type> typeVarMap = buildTypeVariableMap(rawClass, targetParam);
    Type[] typeArgs = genericParam.getActualTypeArguments();
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        Type resolved = resolveType(typeArgs[i], typeVarMap);
        result[i] = toClass(resolved);
        if (result[i] == null) {
            return null;
        }
    }
    return result;
}

private static ParameterizedType findParameterizedType(Class<?> target, Class<?> raw) {
    // Check interfaces
    for (Type it : target.getGenericInterfaces()) {
        ParameterizedType pt = extractParameterizedType(it, raw);
        if (pt != null) {
            return pt;
        }
    }
    // Check superclass
    Type superT = target.getGenericSuperclass();
    if (superT != null) {
        ParameterizedType pt = extractParameterizedType(superT, raw);
        if (pt != null) {
            return pt;
        }
    }
    return null;
}

private static ParameterizedType extractParameterizedType(Type type, Class<?> raw) {
    if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        Type rawT = pt.getRawType();
        if (rawT instanceof Class && rawT.equals(raw)) {
            return pt;
        }
        if (rawT instanceof Class) {
            ParameterizedType found = findParameterizedType((Class<?>) rawT, raw);
            if (found != null) {
                return found;
            }
        }
    } else if (type instanceof Class) {
        Class<?> cls = (Class<?>) type;
        if (cls != null) {
            ParameterizedType found = findParameterizedType(cls, raw);
            if (found != null) {
                return found;
            }
        }
    }
    return null;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> rawClass, ParameterizedType targetPT) {
    Map<TypeVariable<?>, Type> map = new HashMap<>();
    TypeVariable<?>[] vars = rawClass.getTypeParameters();
    Type[] args = targetPT.getActualTypeArguments();
    for (int i = 0; i < vars.length && i < args.length; i++) {
        map.put(vars[i], args[i]);
    }
    return map;
}

private static Type resolveType(Type t, Map<TypeVariable<?>, Type> map) {
    if (t instanceof Class) {
        return t;
    }
    if (t instanceof ParameterizedType) {
        // Return the raw type of the parameterized type
        return ((ParameterizedType) t).getRawType();
    }
    if (t instanceof TypeVariable) {
        Type mapped = map.get(t);
        if (mapped != null) {
            return resolveType(mapped, map);
        } else {
            return null;
        }
    }
    if (t instanceof WildcardType) {
        Type[] upper = ((WildcardType) t).getUpperBounds();
        if (upper.length > 0) {
            return resolveType(upper[0], map);
        } else {
            return null;
        }
    }
    return null;
}

private static Class<?> toClass(Type t) {
    if (t == null) {
        return null;
    }
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    }
    if (t instanceof ParameterizedType) {
        Type raw = ((ParameterizedType) t).getRawType();
        if (raw instanceof Class<?>) {
            return (Class<?>) raw;
        }
    }
    return null;
}

@Override public void accept(final METRICS data) {
    if (data == null) {
        return; // nothing to do
    }

    // Assume that METRICS has a method to provide a unique key used in the cache.
    // Adjust the method name if your METRICS class provides something else.
    final Object key = data.getKey();

    // Retrieve the current cached value, if any.
    METRICS current = cache.get(key);

    if (current == null) {
        // No existing value – simply put the new one into the cache.
        cache.put(key, data);
    } else {
        // Merge the incoming data into the cached value.
        // The METRICS type must provide a merge/mergeWith method that updates the
        // existing instance with information from the new instance.
        current.mergeWith(data);
    }
}

