}

@Override
public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    // Fetch a key that uniquely identifies the metric. This method is assumed to exist on:
    // METRICS. Adjust the key derivation logic to match the actual implementation.
    String key = data.getKey();

    // Attempt to retrieve an existing entry from the cache.
    METRICS existing = cache.get(key);
    if (existing != null) {
        // Merge the new data into the existing entry. The METRICS type is
        // expected to provide a merge method that combines two instances.
        existing.merge(data);
    } else {
        // If no existing value, simply insert the new data.
        cache.put(key, data);
    }
}

