public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return null;
    }
    // Retrieve the current index mapping for the given table name
    Mappings currentMapping = getCurrentIndexMapping(tableName);
    if (currentMapping == null) {
        // If there is no current mapping, treat all fields as new
        return mappings;
    }

    // Extract the 'properties' sections (most likely the field definitions)
    Object currentPropsObj = currentMapping.get("properties");
    Object inputPropsObj = mappings.get("properties");

    if (!(currentPropsObj instanceof Map) || !(inputPropsObj instanceof Map)) {
        // If the structure is unexpected, return the input as is
        return mappings;
    }

    @SuppressWarnings("unchecked")
    Map<String, Object> currentProps = (Map<String, Object>) currentPropsObj;
    @SuppressWarnings("unchecked")
    Map<String, Object> inputProps = (Map<String, Object>) inputPropsObj;

    Map<String, Object> newProps = new HashMap<>();

    for (Map.Entry<String, Object> entry : inputProps.entrySet()) {
        String field = entry.getKey();
        // Skip the special _source field to avoid update conflicts
        if ("_source".equals(field)) {
            continue;
        }
        if (!currentProps.containsKey(field)) {
            newProps.put(field, entry.getValue());
        }
    }

    // Build the resulting mapping JSON
    Map<String, Object> resultMap = new HashMap<>();
    resultMap.put("properties", newProps);
    return new Mappings(resultMap);
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the desired mapping for the table. This method must be provided by the
    // surrounding class and is expected to return a Mappings instance that contains
    // the target schema for the table.
    Mappings desired = getDesiredMappingsForTable(tableName);
    if (desired == null) {
        // Nothing to diff
        return new Mappings();
    }

    @SuppressWarnings("unchecked")
    Map<String, Object> desiredProps =
            (Map<String, Object>) ((Map<String, Object>) desired.source()).get("properties");
    @SuppressWarnings("unchecked")
    Map<String, Object> currentProps =
            (Map<String, Object>) ((Map<String, Object>) mappings.source()).get("properties");

    if (desiredProps == null) {
        desiredProps = Collections.emptyMap();
    }
    if (currentProps == null) {
        currentProps = Collections.emptyMap();
    }

    Map<String, Object> diffProps = new LinkedHashMap<>();
    for (Map.Entry<String, Object> entry : desiredProps.entrySet()) {
        String field = entry.getKey();
        // Skip the special _source field
        if ("_source".equals(field)) {
            continue;
        }
        if (!currentProps.containsKey(field)) {
            diffProps.put(field, entry.getValue());
        }
    }

    if (diffProps.isEmpty()) {
        return new Mappings();
    }

    Map<String, Object> diffSource = new LinkedHashMap<>();
    diffSource.put("properties", diffProps);
    return new Mappings(diffSource);
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve current index mapping from Elasticsearch
    Map<String, Object> currentMapping;
    try {
        currentMapping = client.indices()
                .getMapping(new GetMappingsRequest().indices(tableName), RequestOptions.DEFAULT)
                .mappings()
                .get(tableName)
                .sourceAsMap();
    } catch (IOException e) {
        // Wrap checked exception into unchecked
        throw new RuntimeException("Failed to fetch mapping for index: " + tableName, e);
    }

    // Remove the _source section to avoid update conflict
    currentMapping.remove("_source");

    // Extract properties from current and historic mappings
    Object currPropsObj = currentMapping.get("properties");
    @SuppressWarnings("unchecked")
    Map<String, Object> currentProps = currPropsObj instanceof Map ? (Map<String, Object>) currPropsObj : Collections.emptyMap();

    Object histPropsObj = mappings.getSourceAsMap().get("properties");
    @SuppressWarnings("unchecked")
    Map<String, Object> historyProps = histPropsObj instanceof Map ? (Map<String, Object>) histPropsObj : Collections.emptyMap();

    // Compute diff: fields present in current mapping but missing in historic mapping
    Map<String, Object> diffProps = new LinkedHashMap<>();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        if (!historyProps.containsKey(entry.getKey())) {
            diffProps.put(entry.getKey(), entry.getValue());
        }
    }

    // Build the resulting mapping structure – only the diffed properties
    Map<String, Object> diffMapping = new HashMap<>();
    diffMapping.put("properties", diffProps);
    return new Mappings(diffMapping);
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // The history mapping is expected to contain the current index's mapping.
    // We return a new mapping that only includes fields that are missing
    // in the current index, excluding the "_source" configuration.
    // For this implementation, we assume `Mappings` behaves like a
    // map with string keys.  Implementers can adjust the logic if
    // `Mappings` is a more complex type.
    if (mappings == null) {
        return null;
    }
    try {
        java.util.Map<String, Object> original = (java.util.Map<String, Object>) mappings;
        java.util.Map<String, Object> diff = new java.util.LinkedHashMap<>();
        for (java.util.Map.Entry<String, Object> entry : original.entrySet()) {
            if (!"_source".equals(entry.getKey())) {
                diff.put(entry.getKey(), entry.getValue());
            }
        }
        return (Mappings) diff;
    } catch (ClassCastException e) {
        // If Mappings is not directly castable to Map, return it unchanged.
        return mappings;
    }
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings current = getCurrentMappings(tableName);
    if (current == null) {
        return null;
    }
    java.util.Map<String, Object> currentProps = current.getProperties();
    java.util.Map<String, Object> historyProps = mappings != null ? mappings.getProperties() : null;
    java.util.Map<String, Object> diffProps = new java.util.HashMap<>();
    for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();
        if ("_source".equals(field)) {
            continue;
        }
        if (historyProps == null || !historyProps.containsKey(field)) {
            diffProps.put(field, entry.getValue());
        }
    }
    if (diffProps.isEmpty()) {
        return null;
    }
    Mappings diff = new Mappings();
    diff.setProperties(diffProps);
    return diff;
}

