    final byte[] b = this.b;
    return ((long)b[offset] << 56)
         | ((long)(b[offset + 1] & 255) << 48)
         | ((long)(b[offset + 2] & 255) << 40)
         | ((long)(b[offset + 3] & 255) << 32)
         | ((long)(b[offset + 4] & 255) << 24)
         | ((long)(b[offset + 5] & 255) << 16)
         | ((long)(b[offset + 6] & 255) << 8)
         | ((long)(b[offset + 7] & 255));
}

