public void put(LoggingEvent o) {
    // If null, do nothing
    if (o == null) {
        return;
    }

    // If the buffer is not full, insert the event
    if (size < buffer.length) {
        buffer[writeIndex] = o;
        writeIndex = (writeIndex + 1) % buffer.length;
        size++;
    }
    // else the buffer is full – silently drop the event
}

public void put(LoggingEvent o){
    if (o == null) return;
    if (count == capacity) {
        // buffer is full; silently drop the event
        return;
    }
    eventBuffer[writePos] = o;
    writePos = (writePos + 1) % capacity;
    count++;
}

public void put(LoggingEvent o){
    if (buffer != null) {
        // Attempt to add the event without blocking. If the buffer is full, offer() returns false and we silently discard the event.
        buffer.offer(o);
    }
}

public void put(LoggingEvent o){
    if (o == null){
        return;
    }
    if (buffer == null){
        return;
    }
    try{
        // Try adding the event to the buffer.  If the buffer is full,
        // offer() returns false and we silently drop the event.
        buffer.offer(o);
    } catch (Exception ignored) {
        // Silently drop the event if the buffer cannot accept it.
    }
}

public void put(LoggingEvent o){
    if (o == null) {
        return;
    }
    // Silently drop if the buffer is already full
    if (count == buffer.length) {
        return;
    }
    buffer[writeIndex] = o;
    writeIndex = (writeIndex + 1) % buffer.length;
    ++count;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    if (end <= start) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long chunkEnd = Math.min(end, current + FETCH_DATA_DURATION);
        ranges.add(new TimeRange(current, chunkEnd));
        current = chunkEnd;
    }
    return ranges;
}

