public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || index < 0 || len < 0) {
        throw new IllegalArgumentException("Invalid arguments");
    }
    final int strLen = str.length();
    int end = index + len;
    if (end > strLen) {
        end = strLen;
    }
    int byteCount = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch <= 0x007F) { // 1-byte sequence
            byteCount += 1;
        } else if (ch <= 0x07FF) { // 2-byte sequence
            byteCount += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF && i + 1 < end
                && str.charAt(i + 1) >= 0xDC00 && str.charAt(i + 1) <= 0xDFFF) { // surrogate pair
            byteCount += 4;
            i++; // skip low surrogate
        } else { // 3-byte sequence (including unpaired surrogates)
            byteCount += 3;
        }
        i++;
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0 || index < 0 || index >= str.length()){
        return 0;
    }
    int end = Math.min(index + len, str.length());
    int size = 0;
    for (int i = index; i < end; i++){
        char ch = str.charAt(i);
        if (ch < 0x80){
            size += 1;
        } else if (ch < 0x800){
            size += 2;
        } else if (Character.isHighSurrogate(ch)){
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))){
                size += 4;
                i++; // skip low surrogate
            } else {
                // malformed surrogate, encode as 3 bytes
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

