public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int cp; // code point
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char lo = str.charAt(i + 1);
            if (Character.isLowSurrogate(lo)) {
                cp = Character.toCodePoint(ch, lo);
                i += 2;
            } else {
                // malformed surrogate sequence, treat as replacement character
                cp = 0xFFFD;
                i++;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // lone low surrogate, treat as replacement character
            cp = 0xFFFD;
            i++;
        } else {
            cp = ch;
            i++;
        }

        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

