public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteLength < 0) throw new IndexOutOfBoundsException("byteLength < 0");
    if (byteOffset < 0) throw new IndexOutOfBoundsException("byteOffset < 0");
    // Ensure we have a backing array
    if (data == null) data = new byte[16];
    int needed = position + byteLength;
    if (needed > data.length) {
        int newSize = Math.max(data.length * 2, needed);
        byte[] newData = new byte[newSize];
        System.arraycopy(data, 0, newData, 0, data.length);
        data = newData;
    }
    if (byteArrayValue == null) {
        // Put byteLength null bytes (zeros)
        for (int i = 0; i < byteLength; i++) {
            data[position + i] = 0;
        }
    } else {
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds source array length");
        }
        System.arraycopy(byteArrayValue, byteOffset, data, position, byteLength);
    }
    position += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteLength == 0) {
        return this;
    }
    int pos = this.pos;
    int newPos = pos + byteLength;
    if (newPos > buf.length) {
        ensureCapacity(newPos);
    }
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, buf, pos, byteLength);
    } else {
        int p = pos;
        int l = byteLength;
        while (l-- > 0) {
            buf[p++] = 0;
        }
    }
    this.pos = newPos;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    if (byteLength <= 0) {
        return this;
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException();
        }
    }
    int newPos = pos + byteLength;
    if (newPos > bytes.length) {
        byte[] newBytes = new byte[Math.max(bytes.length << 1, newPos)];
        System.arraycopy(bytes, 0, newBytes, 0, pos);
        bytes = newBytes;
    }
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            bytes[pos + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, bytes, pos, byteLength);
    }
    pos = newPos;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength cannot be negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteLength extends beyond byteArrayValue");
        }
    }

    int oldLen = this.length;
    int newLen = oldLen + byteLength;
    if (newLen > this.bytes.length) {
        int newCap = Math.max(newLen, this.bytes.length * 2);
        byte[] newBytes = new byte[newCap];
        System.arraycopy(this.bytes, 0, newBytes, 0, oldLen);
        this.bytes = newBytes;
    }

    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.bytes, oldLen, byteLength);
    } else {
        // fill with zeros
        for (int i = 0; i < byteLength; ++i) {
            this.bytes[oldLen + i] = 0;
        }
    }

    this.length = newLen;
    return this;
}

