public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    for (int i = 0; i < len; ) {
        int cp = Character.codePointAt(str, i);
        int byteCount;
        if (cp <= 0x7F) {
            byteCount = 1;
        } else if (cp <= 0x7FF) {
            byteCount = 2;
        } else if (cp <= 0xFFFF) {
            byteCount = 3;
        } else {
            byteCount = 4;
        }
        // Ensure the buffer has enough space for the UTF‑8 bytes.
        lb.ensureRemaining(byteCount);
        switch (byteCount) {
            case 1:
                lb.addByte((byte) cp);
                break;
            case 2:
                lb.addByte((byte) (0xC0 | (cp >> 6)));
                lb.addByte((byte) (0x80 | (cp & 0x3F)));
                break;
            case 3:
                lb.addByte((byte) (0xE0 | (cp >> 12)));
                lb.addByte((byte) (0x80 | ((cp >> 6) & 0x3F)));
                lb.addByte((byte) (0x80 | (cp & 0x3F)));
                break;
            case 4:
                lb.addByte((byte) (0xF0 | (cp >> 18)));
                lb.addByte((byte) (0x80 | ((cp >> 12) & 0x3F)));
                lb.addByte((byte) (0x80 | ((cp >> 6) & 0x3F)));
                lb.addByte((byte) (0x80 | (cp & 0x3F)));
                break;
        }
        i += Character.charCount(cp);
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int i = 0;
    final int len = str.length();
    while (i < len) {
        int codePoint = str.codePointAt(i);
        i += Character.charCount(codePoint);
        if (codePoint < 0x80) {
            lb.write((byte) codePoint);
        } else if (codePoint < 0x800) {
            lb.write((byte)((codePoint >> 6) | 0xC0));
            lb.write((byte)((codePoint & 0x3F) | 0x80));
        } else if (codePoint < 0x10000) {
            lb.write((byte)((codePoint >> 12) | 0xE0));
            lb.write((byte)(((codePoint >> 6) & 0x3F) | 0x80));
            lb.write((byte)((codePoint & 0x3F) | 0x80));
        } else {
            lb.write((byte)((codePoint >> 18) | 0xF0));
            lb.write((byte)(((codePoint >> 12) & 0x3F) | 0x80));
            lb.write((byte)(((codePoint >> 6) & 0x3F) | 0x80));
            lb.write((byte)((codePoint & 0x3F) | 0x80));
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    final int length = str.length();
    for (int i = 0; i < length; i++) {
        final char ch = str.charAt(i);
        if (ch < 0x80) { // 1-byte sequence
            lb.append((byte) ch);
        } else if (ch < 0x800) { // 2-byte sequence
            lb.append((byte) (0xC0 | (ch >> 6)));
            lb.append((byte) (0x80 | (ch & 0x3F)));
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // possible high surrogate
            if (i + 1 < length) {
