                if (low >= 0xDC00 && low <= 0xDFFF) { // low surrogate
                    final int codePoint = 0x10000 + (((ch - 0xD800) << 10) | (low - 0xDC00));
                    lb.append((byte) (0xF0 | (codePoint >> 18)));
                    lb.append((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
                    lb.append((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
                    lb.append((byte) (0x80 | (codePoint & 0x3F)));
                    i++; // skip low surrogate
                    continue;
                }
            }
            // If not a valid surrogate pair, encode the high surrogate as a replacement character U+FFFD
            final int replacement = 0xFFFD;
            lb.append((byte) (0xE0 | (replacement >> 12)));
            lb.append((byte) (0x80 | ((replacement >> 6) & 0x3F)));
            lb.append((byte) (0x80 | (replacement & 0x3F)));
        } else { // 3-byte sequence
            lb.append((byte) (0xE0 | (ch >> 12)));
            lb.append((byte) (0x80 | ((ch >> 6) & 0x3F)));
            lb.append((byte) (0x80 | (ch & 0x3F)));
        }
    }
    return lb;
}

