private static String substitute(String input, Properties props, java.util.Set<String> seen) {
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)}");
    java.util.regex.Matcher m = pattern.matcher(input);
    StringBuilder sb = new StringBuilder();
    int lastIndex = 0;
    while (m.find()) {
        sb.append(input, lastIndex, m.start());
        String var = m.group(1);
        if (seen.contains(var)) {
            // Avoid infinite recursion
            sb.append(m.group(0)); // leave placeholder as is
        } else {
            String replacement = props.getProperty(var);
            if (replacement != null) {
                // Recursively substitute inside the replacement
                java.util.Set<String> newSeen = new java.util.HashSet<>(seen);
                newSeen.add(var);
                replacement = substitute(replacement, props, newSeen);
                sb.append(replacement);
            } else {
                // If property not found, replace with empty string or keep placeholder
                sb.append(""); // empty
            }
        }
        lastIndex = m.end();
    }
    sb.append(input, lastIndex, input.length());
    return sb.toString();
}

public static String findAndSubst(String key, Properties props){
    if(props == null) return null;
    String value = props.getProperty(key);
    if(value == null) return null;
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    int maxDepth = 10;
    int depth = 0;
    while(depth < maxDepth){
        java.util.regex.Matcher matcher = pattern.matcher(value);
        boolean found = false;
        StringBuffer sb = new StringBuffer();
        while(matcher.find()){
            found = true;
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if(replacement == null) replacement = "";
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(sb);
        value = sb.toString();
        if(!found) break;
        depth++;
    }
    return value;
}

