private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, treat as a match
    if (str == null && suffix == null) {
        return true;
    }
    // If only one is null, not a match
    if (str == null || suffix == null) {
        return false;
    }

    int strLen = str.length();
    int sufLen = suffix.length();

    // Suffix longer than string cannot match
    if (sufLen > strLen) {
        return false;
    }

    // If suffix is empty, every string ends with an empty suffix
    if (sufLen == 0) {
        return true;
    }

    if (ignoreCase) {
        // Use regionMatches with ignoreCase
        return str.regionMatches(true, strLen - sufLen, suffix, 0, sufLen);
    } else {
        // Use standard endsWith
        return str.endsWith(suffix);
    }
}

