public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Ignore the leading slash for absolute path components
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split by '/' while preserving trailing empty segments
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, keep the original segment
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

