        }
        result |= (long)(b & 0x7F) << shift;   // accumulate the 7 data bits
        if ((b & 0x80) == 0) {
            return result;                     // last byte, return value
        }
        shift += 7;
    }
    throw new IOException("Varint64 too long");
}

