                // Handle base type of the array.
                if (i >= args.length()) {
                    throw new IllegalArgumentException("Incomplete array descriptor in: " + descriptor);
                }
                if (args.charAt(i) == 'L') {
                    i++; // skip 'L'
                    int endIdx = args.indexOf(';', i);
                    if (endIdx == -1) {
                        throw new IllegalArgumentException("Missing ';' in object array descriptor in: " + descriptor);
                    }
                    i = endIdx + 1;
                } else {
                    i++; // primitive type
                }
                count++;
            } else if (c == 'L') {
                // Object type – skip until ';'.
                i++; // skip 'L'
                int endIdx = args.indexOf(';', i);
                if (endIdx == -1) {
                    throw new IllegalArgumentException("Missing ';' in object descriptor in: " + descriptor);
                }
                i = endIdx + 1;
                count++;
            } else {
                // Primitive type.
                i++;
                count++;
            }
        }
    } else {
        // Field descriptor – pop the single type described.
        String args = descriptor;
        int i = 0;
        while (i < args.length()) {
            char c = args.charAt(i);
            if (c == '[') {
                while (i < args.length() && args.charAt(i) == '[') {
                    i++;
                }
                if (i >= args.length()) {
                    throw new IllegalArgumentException("Incomplete array descriptor in: " + descriptor);
                }
                if (args.charAt(i) == 'L') {
                    i++; // skip 'L'
                    int endIdx = args.indexOf(';', i);
                    if (endIdx == -1) {
                        throw new IllegalArgumentException("Missing ';' in object array descriptor in: " + descriptor);
                    }
                    i = endIdx + 1;
                } else {
                    i++; // primitive type
                }
                count++;
            } else if (c == 'L') {
                i++; // skip 'L'
                int endIdx = args.indexOf(';', i);
                if (endIdx == -1) {
                    throw new IllegalArgumentException("Missing ';' in object descriptor in: " + descriptor);
                }
                i = endIdx + 1;
                count++;
            } else {
                i++;
                count++;
            }
        }
    }

    // Pop the calculated number of abstract types from the output stack.
    for (int j = 0; j < count; j++) {
