private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    if (descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')');
        if (end == -1){
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        int idx = 1;
        while (idx < end){
            int slots = slotsFor(descriptor, idx);
            for (int s = 0; s < slots; s++){
                stack.pop();
            }
            idx = skipType(descriptor, idx);
        }
    } else {
        int slots = slotsFor(descriptor, 0);
        for (int s = 0; s < slots; s++){
            stack.pop();
        }
    }
}

private int skipType(String desc, int index){
    int i = index;
    while (i < desc.length() && desc.charAt(i) == '['){
        i++;
    }
    if (i >= desc.length()){
        return i;
    }
    char c = desc.charAt(i);
    if (c == 'L'){
        i++;
        while (i < desc.length() && desc.charAt(i) != ';'){
            i++;
        }
        if (i < desc.length()){
            i++; // skip ';'
        }
    } else {
        i++; // primitive or void
    }
    return i;
}

private int slotsFor(String desc, int index){
    int i = index;
    while (i < desc.length() && desc.charAt(i) == '['){
        i++;
    }
    if (i >= desc.length()){
        return 0;
    }
    char c = desc.charAt(i);
    if (c == 'J' || c == 'D'){
        return 2;
    } else if (c == 'V'){
        return 0;
    } else {
        return 1;
    }
}

