    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int index = 0;
    if (descriptor.charAt(0) == '('){
        index++; // skip '('
        while (descriptor.charAt(index) != ')'){
            index = skipType(descriptor, index);
            // pop a single entry from the output frame stack
            outputFrameStack.pop();
        }
        // ignore return type
    } else {
        // single type descriptor
        outputFrameStack.pop();
    }
}

/** Skip over one type descriptor starting at position pos and return the next position. */
private int skipType(String desc, int pos){
    char c = desc.charAt(pos);
    if (c == '['){
        // Skip all '[' characters
        while (desc.charAt(pos) == '['){
            pos++;
        }
        // Then skip the base type
        return skipType(desc, pos);
    } else if (c == 'L'){
        pos++; // skip 'L'
        // Skip until ';'
        while (desc.charAt(pos) != ';'){
            pos++;
        }
        return pos + 1; // include ';'
    } else {
        // Primitive type: single char
        return pos + 1;
    }
}

