    edges.add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        return;
    }
    // Ensure the map for the source vertex exists
    Map<V, Set<E>> targetMap = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());
    // Add the edge to the set for the target vertex
    targetMap.computeIfAbsent(targetVertex, k -> new HashSet<>()).add(e);
}

