    int newSize = buf.length + Math.max(buf.length >> 1, size) + 1;
    byte[] newBuf = new byte[newSize];
    System.arraycopy(buf, start, newBuf, 0, used);
    buf = newBuf;
    start = 0;
}

private void enlarge(final int size){
    // Ensure there is enough room for 'size' additional bytes.
    // If the buffer is already big enough, do nothing.
    if (buffer == null) {
        // If the buffer hasn't been allocated yet, give it an initial size.
        int initialCapacity = Math.max(16, size);
        buffer = new byte[initialCapacity];
        return;
    }

    int needed = used + size;          // total bytes needed
    if (needed <= buffer.length)      // already enough space
        return;

    // Grow the buffer: increase by at least 50% to reduce frequent reallocations
    int newCapacity = Math.max(buffer.length + (buffer.length >> 1), needed);

    // Allocate a new buffer and copy the existing data
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(buffer, 0, newBuffer, 0, used);
    buffer = newBuffer;
}

private void enlarge(final int size){
    // Add no extra capacity if requested size is non‑positive
    if (size <= 0) {
        return;
    }

    // Number of bytes that will be occupied after the new data is added
    int requiredCapacity = this.size + size;

    // If the current buffer can already accommodate the new bytes, nothing to do
    if (requiredCapacity <= array.length) {
        return;
    }

    // Grow strategy: double the current capacity or use requiredCapacity, whichever is larger
    int newCapacity = Math.max(array.length << 1, requiredCapacity);

    byte[] newArray = new byte[newCapacity];
    System.arraycopy(array, 0, newArray, 0, this.size);
    array = newArray;
}

