private boolean containsAllFields(Fields fields) {
    if (fields == null) {
        return false;
    }
    // Assume the class has a Map<String,Object> named propertyStore that holds stored fields
    if (propertyStore == null || propertyStore.isEmpty()) {
        return false;
    }
    // If Fields implements Iterable, iterate directly
    if (fields instanceof Iterable) {
        for (Object obj : (Iterable<?>) fields) {
            String key = obj.toString();
            if (!propertyStore.containsKey(key)) {
                return false;
            }
        }
        return true;
    }
    // Fallback: try to retrieve a collection of field names via a likely method
    try {
        Object result = fields.getClass().getMethod("getFields").invoke(fields);
        if (result instanceof Collection) {
            for (Object obj : (Collection<?>) result) {
                String key = obj.toString();
                if (!propertyStore.containsKey(key)) {
                    return false;
                }
            }
            return true;
        }
    } catch (Exception ignored) {
        // Method not found or inaccessible; safely return false
    }
    return false;
}

