    try {
        for (java.lang.reflect.Field f : fields.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            Object value = f.get(fields);
            if (value instanceof String) {
                if (!properties.containsKey((String) value)) {
                    return false;
                }
            } else if (value instanceof java.util.Collection) {
                for (Object obj : (java.util.Collection<?>) value) {
                    if (obj instanceof String && !properties.containsKey((String) obj)) {
                        return false;
                    }
                }
            }
        }
        return true;
    } catch (Exception e) {
        return false;
    }
}

