public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    LinkedBuffer cur = node;
    while (cur != null) {
        // Write current buffer segment to the output
        out.write(cur.buf, 0, cur.tail);
        total += cur.tail;
        // Move to next segment
        cur = cur.next;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    while (node != null) {
        out.write(node.buf, 0, node.ptr);
        total += node.ptr;
        node = node.next;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        out.write(current.buf, 0, current.size);
        totalSize += current.size;
        current = current.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Obtain the underlying byte array and the range that contains data.
        byte[] buffer = current.getArray();
        int start = current.getStart();
        int end = current.getEnd();
        int length = end - start;

        // Write the contents to the DataOutput.
        out.write(buffer, start, length);
        totalSize += length;

        // Move to the next linked buffer in the chain.
        current = current.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    while (node != null) {
        byte[] buf = node.getData();          // the underlying byte array
        int off = node.getOffset();           // starting position in the array
        int len = node.getLength();           // number of valid bytes in this segment
        out.write(buf, off, len);
        total += len;
        node = node.getNext();                // move to the next buffer segment
    }
    return total;
}

