private void putAbstractTypes(final int start, final int end) {
    // Write verification_type_info entries for the abstract types in currentFrame
    // between indices start (inclusive) and end (exclusive), according to the JVMS
    // specification for StackMapTable attributes.
    for (int i = start; i < end; i++) {
        byte tag = currentFrame.get(i);
        stackMapTableEntries.writeByte(tag);
        // For tags 7 (Object) and 8 (Uninitialized) we need to output an additional
        // 2‑byte operand (cp_index or offset respectively).
        if (tag == 7 || tag == 8) {
            // The operand is stored immediately after the tag in currentFrame.
            short operand = currentFrame.get(i + 1);
            stackMapTableEntries.writeShort(operand);
            i++; // Skip the operand that has just been written
        }
    }
}

