private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++){
        AbstractType type = currentFrame[i];
        int tag = type.getTag();
        stackMapTableEntries[stackMapTablePos++] = (byte) tag;
        if (tag == AbstractType.OBJECT || tag == AbstractType.UNINITIALIZED){
            int index = type.getIndex();
            stackMapTableEntries[stackMapTablePos++] = (byte) ((index >> 8) & 0xFF);
            stackMapTableEntries[stackMapTablePos++] = (byte) (index & 0xFF);
        }
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream must not be null");
    }
    // Clear the current buffer and reset the read pointer.
    this.buffer = new byte[0];
    this.readPointer = 0;

    // Read all bytes from the input stream into a temporary buffer.
    ByteArrayOutputStream temp = new ByteArrayOutputStream();
    byte[] chunk = new byte[8192];
    int bytesRead;
    while ((bytesRead = in.read(chunk)) != -1) {
        temp.write(chunk, 0, bytesRead);
    }

    // Replace the buffer with the newly read data and reset the pointer.
    this.buffer = temp.toByteArray();
    this.readPointer = 0;
}

