@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Expecting conversion only to Character or char
    if (!Character.class.isAssignableFrom(type) && !type.equals(char.class)) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }

    if (value == null) {
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }

    // String or CharSequence of length 1
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return cs.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert CharSequence to Character, length != 1: " + value);
        }
    }

    // Numeric types: take numeric value and cast to char
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }

    // Fallback: use toString() representation
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    throw new IllegalArgumentException("Cannot convert value to Character: " + value);
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Only support conversion to java.lang.Character or primitive char
    if (type == null) {
        throw new Exception("Target type is null");
    }

    // Handle primitive char
    final boolean isCharPrimitive = (type == char.class);
    final boolean isCharacterCls   = (type == Character.class);

    if (!isCharPrimitive && !isCharacterCls) {
        throw new Exception("Unsupported target type: " + type.getName());
    }

    // If value is null
    if (value == null) {
        // Primitive cannot be null
        if (isCharPrimitive) {
            throw new Exception("Cannot convert null to primitive char");
        }
        return null;
    }

    // If value is already a Character
    if (value instanceof Character) {
        return value; // already Character
    }

    // If value is a String
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new Exception("String length > 1 cannot be converted to char");
        }
    }

    // If value is a Number (e.g., Integer, Long, etc.)
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        char c = (char) intVal;
        return Character.valueOf(c);
    }

    // If value is a Boolean or other type, attempt to use its string representation
    // but only if it's a single character
    String valStr = value.toString();
    if (valStr.length() == 1) {
        return Character.valueOf(valStr.charAt(0));
    }

    // If we cannot convert
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Only support conversion to java.lang.Character (or primitive char)
    if (!Character.class.isAssignableFrom(type) && !type.equals(char.class)) {
        throw new Exception("Unsupported target type: " + type.getName());
    }

    if (value == null) {
        return null;
    }

    if (value instanceof Character) {
        return value;
    }

    if (value instanceof String) {
        String str = (String) value;
        if (str.isEmpty()) {
            throw new Exception("Cannot convert empty string to Character");
        }
        return Character.valueOf(str.charAt(0));
    }

    if (value instanceof Number) {
        // Cast the numeric value to a char (by converting to int first)
        int intValue = ((Number) value).intValue();
        return Character.valueOf((char) intValue);
    }

    // Attempt to use toString, if the string representation has length 1
    String s = value.toString();
    if (s.length() == 1) {
        return Character.valueOf(s.charAt(0));
    }

    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character (or primitive char)
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }

    if (value == null) {
