        String str = (String) value;
        if (str.isEmpty()) {
            throw new IllegalArgumentException("Cannot convert empty string to Character");
        }
        return Character.valueOf(str.charAt(0));
    }

    if (value instanceof Number) {
        // Convert numeric value to its corresponding char
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }

    // Attempt to convert using the string representation of the value
    String str = value.toString();
    if (str.isEmpty()) {
        throw new IllegalArgumentException("Cannot convert to Character: empty string representation");
    }
    return Character.valueOf(str.charAt(0));
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Support only Character or char types
    if (type == Character.class || type == char.class) {
        if (value == null) {
            return null;
        }
        // If already a Character, return as is
        if (value instanceof Character) {
            return value;
        }
        // If String, take first and only character
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return Character.valueOf(str.charAt(0));
            }
            throw new Exception("String cannot be converted to Character: length != 1");
        }
        // Accept CharSequence
        if (value instanceof CharSequence) {
            CharSequence cs = (CharSequence) value;
            if (cs.length() == 1) {
                return Character.valueOf(cs.charAt(0));
            }
            throw new Exception("CharSequence cannot be converted to Character: length != 1");
        }
        // If a number, interpret as Unicode code point
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            return Character.valueOf((char) intVal);
        }
        // Unsupported source type for Character conversion
        throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
    }
    // For any other target type, no conversion performed
    return null;
}

