public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    // ensure odd
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    while (true) {
        if (isPrime(candidate)) return candidate;
        candidate += 2; // skip even numbers
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int r = (int)Math.sqrt(n);
    for (int i = 5; i <= r; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    int n = desiredCapacity;
    if ((n & 1) == 0) n++; // Ensure n is odd
    while (true) {
        int candidate = n;
        boolean prime = true;
        if (candidate <= 3) {
            prime = true;
        } else {
            if (candidate % 2 == 0 || candidate % 3 == 0) {
                prime = false;
            } else {
                int i = 5;
                while (i * i <= candidate) {
                    if (candidate % i == 0 || candidate % (i + 2) == 0) {
                        prime = false;
                        break;
                    }
                    i += 6;
                }
            }
        }
        if (prime) return candidate;
        if (n > Integer.MAX_VALUE - 2) {
            return Integer.MAX_VALUE;
        }
        n += 2;
    }
}

