    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }
    while (!isPrime(candidate)) {
        candidate += 2; // skip even numbers
        // Safety guard for overflow: if candidate goes beyond Integer.MAX_VALUE, return Integer.MAX_VALUE
        if (candidate < 0) {
            return Integer.MAX_VALUE;
        }
    }
    return candidate;
}

