                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                // Universal character name
                int remaining = length - i - 1;
                if (remaining < 4) {
                    // not enough digits, treat literally
                    sb.append('\\').append('u');
                } else {
                    String hex = str.substring(i + 1, i + 5);
                    boolean validHex = true;
                    for (int k = 0; k < 4; k++) {
                        char hc = hex.charAt(k);
                        if (!((hc >= '0' && hc <= '9') ||
                              (hc >= 'A' && hc <= 'F') ||
                              (hc >= 'a' && hc <= 'f'))) {
