public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch != '\\') {
            result.append(ch);
            continue;
        }
        // Found a backslash
        if (i + 1 >= len) {
            // Backslash at end of string: treat as literal
            result.append('\\');
            break;
        }
        char next = str.charAt(i + 1);
        if (next == '\\') {
            // Escaped backslash: produce single backslash
            result.append('\\');
            i++; // Skip the next backslash
            continue;
        }
        switch (next) {
            case 'b':
                result.append('\b');
                break;
            case 't':
                result.append('\t');
                break;
            case 'n':
                result.append('\n');
                break;
            case 'f':
                result.append('\f');
                break;
            case 'r':
                result.append('\r');
                break;
            case '\'':
                result.append('\'');
                break;
            case '\"':
                result.append('\"');
                break;
            case 'u':
                // Unicode escape: \uXXXX
                if (i + 5 < len) {
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        result.append((char) code);
                        i += 5; // consumed \uXXXX
                        continue;
                    } catch (NumberFormatException e) {
                        // Invalid escape, treat as literal
                        result.append('\\').append('u');
                    }
                } else {
                    // Not enough chars, treat literally
                    result.append('\\').append('u');
                }
                break;
            default:
                // Octal or other escape? Handle up to three octal digits 0-7
                if (next >= '0' && next <= '7') {
                    int j = i + 1;
                    int val = 0;
                    int count = 0;
                    while (j < len && count < 3) {
                        char d = str.charAt(j);
                        if (d >= '0' && d <= '7') {
                            val = val * 8 + (d - '0');
                            j++;
                            count++;
                        } else {
                            break;
                        }
                    }
                    result.append((char) val);
                    i = j - 1; // adjust for loop increment
                } else {
                    // Unrecognized escape, keep as is
                    result.append('\\').append(next);
                }
                break;
        }
        i++; // Skip the escape character
    }
    return result.toString();
}

