    // Choose the smaller set to iterate over for better performance
    if (set1 == null || set2 == null) {
        return Collections.emptySet();
    }
    Set<V> small = set1.size() <= set2.size() ? set1 : set2;
    Set<V> large = set1.size() <= set2.size() ? set2 : set1;

    Set<V> result = new HashSet<>(small.size());
    for (V element : small) {
        if (large.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

