protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int[] removed = new int[1];
    root = prune(root, removed);
    return removed[0];
}

private CategoryNode prune(CategoryNode node, int[] removed) {
    if (node == null) {
        return null;
    }
    if (!node.isActive()) {
        removed[0] += countNodes(node);
        return null;
    }
    List<CategoryNode> children = node.getChildren();
    for (int i = children.size() - 1; i >= 0; i--) {
        CategoryNode child = children.get(i);
        CategoryNode pruned = prune(child, removed);
        if (pruned == null) {
            children.remove(i);
        } else {
            children.set(i, pruned);
        }
    }
    return node;
}

private int countNodes(CategoryNode node) {
    int count = 1;
    for (CategoryNode child : node.getChildren()) {
        count += countNodes(child);
    }
    return count;
}

protected int removeUnusedNodes() {
    int removed = 0;
    // Remove unused nodes from children first
    for (int i = children.size() - 1; i >= 0; i--) {
        Category child = children.get(i);
        removed += child.removeUnusedNodes();
    }
    // If this node is inactive and has no remaining children, remove it
    if (!isActive() && children.isEmpty()) {
        if (parent != null) { // root nodes without parent are not removed
            parent.children.remove(this);
        }
        removed += 1;
    }
    return removed;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    // If the root itself is inactive, remove the entire tree
    if (!root.isActive()) {
        int total = computeSubtreeSize(root);
        root = null;
        return total;
    }

    int removed = 0;
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);

    while (!stack.isEmpty()) {
        Category current = stack.pop();
        List<Category> children = current.getChildren();
        Iterator<Category> it = children.iterator();

        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                removed += computeSubtreeSize(child);
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

/**
 * Recursively calculates the number of nodes in a subtree.
 */
private int computeSubtreeSize(Category node) {
    int size = 1; // Count the node itself
    for (Category child : node.getChildren()) {
        size += computeSubtreeSize(child);
    }
    return size;
}

protected int removeUnusedNodes() {
    final int[] removedCount = {0};
    root = pruneNode(root, removedCount);
    return removedCount[0];
}

private CategoryNode pruneNode(CategoryNode node, int[] removedCount) {
    if (node == null) {
        return null;
    }
    // Process children first
    for (int i = node.getChildren().size() - 1; i >= 0; i--) {
        CategoryNode child = node.getChildren().get(i);
        CategoryNode prunedChild = pruneNode(child, removedCount);
        if (prunedChild == null) {
            node.getChildren().remove(i);
        }
    }
    // If this node is inactive, remove it
    if (!node.isActive()) {
        removedCount[0]++;
        return null;
    }
    return node;
}

protected int removeUnusedNodes() {
    // Count of nodes removed
    int removed = 0;

    // If the root itself is inactive, drop the entire tree
    if (root != null && !root.isActive()) {
        root = null;
        return 1;
    }

    // Recursive helper to clean children of each node
    java.util.List<Category> children = (root != null) ? root.getChildren() : null;
    if (children != null) {
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                removed++; // Increment count for this removed node
            } else {
                // Recurse into the child's subtree
                removed += removeUnusedFromNode(child);
            }
        }
    }
    return removed;
}

/**
 * Recursively removes inactive nodes from the subtree rooted at {@code node}.
 *
 * @param node the root of the subtree to clean
 * @return number of nodes removed from this subtree
 */
private int removeUnusedFromNode(Category node) {
    int removed = 0;
    java.util.List<Category> children = node.getChildren();
    if (children != null) {
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                removed++;
            } else {
                removed += removeUnusedFromNode(child);
            }
        }
    }
    return removed;
}

