final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // The offset of each constant-pool entry is stored in the array `constantPoolEntryOffset`;
    // it is assumed that this field has been initialized by the class constructor.
    int offset = constantPoolEntryOffset[constantPoolEntryIndex];
    // The first byte of the entry is the tag.
    if ((classFileBuffer[offset++] & 0xFF) != 1) {
        // Not a CONSTANT_Utf8 entry – return null or throw an exception as appropriate.
        return null;
    }
    // The next two bytes give the length of the UTF-8 byte sequence.
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    // Safety check: make sure we do not read past the buffer.
    if (length < 0 || offset + length > classFileBuffer.length) {
        return null;
    }
    // Convert the bytes to a Java String using UTF‑8 encoding.
    java.nio.charset.Charset utf8 = java.nio.charset.Charset.forName("UTF-8");
    String result = new String(classFileBuffer, offset, length, utf8);
    // Copy the characters into the supplied buffer, if it is large enough.
    if (charBuffer == null || charBuffer.length < result.length()) {
        return null; // buffer too small; caller should handle this situation.
    }
    result.getChars(0, result.length(), charBuffer, 0);
    return result;
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    /* Assume constantPoolOffsets[constantPoolEntryIndex] gives the offset of the
       CONSTANT_Utf8 entry (tag byte). */
    int offset = constantPoolOffsets[constantPoolEntryIndex];
    if (classFileBuffer[offset] != 1) {
        throw new IllegalArgumentException(
            "Constant at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    int ulen = ((classFileBuffer[offset + 1] & 0xFF) << 8) |
               (classFileBuffer[offset + 2] & 0xFF);
    int utfStart = offset + 3;      // start of the UTF-8 byte sequence

    try {
        java.io.DataInputStream din = new java.io.DataInputStream(
            new java.io.ByteArrayInputStream(classFileBuffer, utfStart, ulen));
        String result = din.readUTF();        // Java's modified UTF-8 reads correctly
        result.getChars(0, result.length(), charBuffer, 0);
        return result;
    } catch (java.io.IOException e) {
        throw new RuntimeException(
            "Failed to read CONSTANT_Utf8 at index " + constantPoolEntryIndex, e);
    }
}

final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Obtain the file offset of the requested constant pool entry
    final int entryOffset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    // The entry is of type CONSTANT_Utf8: 1-byte tag, 2-byte length, followed by UTF‑8 bytes
    final int length = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8)
                     |  (classFileBuffer[entryOffset + 2] & 0xFF);
    // Read the raw bytes and convert them to chars
    for(int i = 0; i < length; i++){
        charBuffer[i] = (char)(classFileBuffer[entryOffset + 3 + i] & 0xFF);
    }
    // Construct and return the string from the filled buffer
    return new String(charBuffer, 0, length);
}

