    // Retrieve the offset of the entry in the class file byte buffer
    int entryOffset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    // Ensure the entry is a CONSTANT_Utf8 (tag value 1)
    if ((classFileBuffer[entryOffset] & 0xFF) != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " +
                                            constantPoolEntryIndex + " is not a UTF8 constant.");
    }
    // Read the length of the UTF8 byte sequence (u2, big-endian)
    int length = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8)
               | (classFileBuffer[entryOffset + 2] & 0xFF);
    int bytesStart = entryOffset + 3; // first byte of the UTF8 string
    // Decode the UTF-8 byte sequence into a String
    String decoded = new String(classFileBuffer, bytesStart, length,
                                java.nio.charset.Charset.forName("UTF-8"));
    // Copy the characters into the provided buffer
    int strLen = decoded.length();
    decoded.getChars(0, strLen, charBuffer, 0);
    // Return a new String instance constructed from the buffer content
    return new String(charBuffer, 0, strLen);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Find the offset of the CONSTANT_Utf8 entry in the constant pool.
    // The constant pool starts after the first 10 bytes (magic + minor_version + major_version + constant_pool_count).
    int offset = 10;
    // Iterate through the constant pool entries to reach the desired index.
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[offset++] & 0xFF;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // Long and Double occupy two constant pool indices
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
                offset += 2;
                break;
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            case 15: // CONSTANT_MethodHandle
                offset += 3; // tag + reference (1+2)
                break;
            case 16: // CONSTANT_MethodType
                offset += 2;
                break;
            case 18: // CONSTANT_InvokeDynamic
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }

    // Now read the target CONSTANT_Utf8 entry.
    int tag = classFileBuffer[offset++] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("constantPoolEntryIndex does not refer to a CONSTANT_Utf8 entry");
    }
    int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    int byteOffset = offset + 2;
    String str = new String(classFileBuffer, byteOffset, len, java.nio.charset.StandardCharsets.UTF_8);

    // Copy characters into the provided buffer.
    int strLen = str.length();
    if (charBuffer.length < strLen) {
        throw new IllegalArgumentException("Provided charBuffer is too small for the UTF-8 string");
    }
    str.getChars(0, strLen, charBuffer, 0);
    return str;
}

