private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize a circulator at the starting node, respecting the traversal direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Continue traversing until we reach the stop node or find a node that satisfies the predicate.
    while (!circ.node().equals(stop) && !predicate.test(circ.node())) {
        // Move to the next or previous node based on the direction.
        circ = dir > 0 ? circ.next() : circ.prev();
    }

    // Return the circulator positioned at the satisfying node or at the stop node.
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Start from the provided node. If the predicate is already satisfied at the start,
    // return immediately.
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    if (predicate.test(circ.getNode())) {
        return circ;
    }

    // Traverse the outer face in the specified direction until we encounter the stop node.
    // At each step, check whether the predicate holds; if so, return the circulator.
    while (!circ.getNode().equals(stop)) {
        circ = circ.next(dir);
        if (predicate.test(circ.getNode())) {
            return circ;
        }
    }

    // If the stop node was reached without finding a satisfying node,
    // return a circulator pointing to the stop node.
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator it = new OuterFaceCirculator(start);
    // If we start at the stop node, return it immediately
    if (it.node() == stop) {
        return it;
    }
    // Traverse until we hit the stop node
    while (true) {
        if (predicate.test(it.node())) {
            return it;
        }
        // Move in the specified direction
