    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    // Automatically suspend the resource according to its transport protocol
    // For long‑polling or WebSocket transports, suspend to keep the connection alive
    if (r.getTransport() != null) {
        r.suspend();
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    // Automatically suspend the AtmosphereResource based on its transport type
    AtmosphereResource.TRANSPORT transport = r.getTransport();
    switch (transport) {
        case WEBSOCKET:
            // WebSocket connections are typically long-lived; suspend indefinitely
            r.suspend(false, -1);
            break;
        case SSE:
            // Server Sent Events may use a moderate suspend timeout
            r.suspend(true, 30_000);
            break;
        default:
            // For HTTP and other transports, suspend with a default timeout
            r.suspend(false, 30_000);
            break;
    }
    return Action.CONTINUE;
}

public double vertexWeight(Set<V> v){
    double sum = 0.0;
