public int appendLoopOnAppenders(LoggingEvent event) {
    int count = 0;
    for (Enumeration<?> e = appenders.immutableEnumeration(); e.hasMoreElements();) {
        Appender appender = (Appender) e.nextElement();
        try {
            appender.doAppend(event);
            count++;
        } catch (Throwable t) {
            // Swallow any exception thrown by an appender to
            // ensure that all appenders get a chance to process the event.
        }
    }
    return count;
}

