protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || tour.isEmpty()){
        return null;
    }
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);

    // Pick arbitrary starting edge to get the first vertex
    Iterator<E> it = remaining.iterator();
    if(!it.hasNext()){
        return null;
    }
    E firstEdge = it.next();
    V start = graph.getEdgeSource(firstEdge);
    vertexList.add(start);
    V current = start;
    double totalWeight = 0.0;

    while(!remaining.isEmpty()){
        boolean found = false;
        // Iterate over a copy of the remaining set to avoid ConcurrentModificationException
        for(E e : new ArrayList<>(remaining)){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if(src.equals(current)){
                // Follow directed or undirected edge from current
                remaining.remove(e);
                edgeList.add(e);
                vertexList.add(tgt);
                current = tgt;
                totalWeight += graph.getEdgeWeight(e);
                found = true;
                break;
            } else if(!graph.getType().isDirected() && tgt.equals(current)){
                // Undirected edge connects to current from the other side
                remaining.remove(e);
                edgeList.add(e);
                vertexList.add(src);
                current = src;
                totalWeight += graph.getEdgeWeight(e);
                found = true;
                break;
            }
        }
        if(!found){
            // No connecting edge found; the tour is incomplete or malformed
            break;
        }
    }

    return new BasicGraphPath<>(graph, vertexList, edgeList, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    // Handle empty tour
    if(tour == null || tour.isEmpty()){
        return new DefaultGraphPath<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0, 0.0, false);
    }

    // Build adjacency list from the edge set
    Map<V, List<E>> adjacency = new HashMap<>();
    for(E e : tour){
        V v1 = graph.getEdgeSource(e);
        V v2 = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(v1, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v2, k -> new ArrayList<>()).add(e);
    }

    // Pick an arbitrary start vertex
    V start = graph.vertexSet().iterator().next();

    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);

    V current = start;
    vertices.add(current);

    while(!remaining.isEmpty()){
        List<E> adjEdges = adjacency.get(current);
        if(adjEdges == null){
            // Invalid tour structure
            break;
        }
        E chosen = null;
        for(E e : adjEdges){
            if(remaining.contains(e)){
                chosen = e;
                break;
            }
        }
        if(chosen == null){
            // No connecting edge left, stop
            break;
        }
        remaining.remove(chosen);

        // Determine next vertex
        V next = graph.getEdgeSource(chosen).equals(current) ? graph.getEdgeTarget(chosen) : graph.getEdgeSource(chosen);
        edges.add(chosen);
        vertices.add(next);
        current = next;
    }

    // Compute total weight of the path
    double totalWeight = 0.0;
    for(E e : edges){
        totalWeight += graph.getEdgeWeight(e);
    }

    return new DefaultGraphPath<>(graph, vertices, edges, totalWeight, totalWeight, false);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    Map<V, List<E>> adjacency = new HashMap<>();
    for(E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }

    V start = null;
    for(Map.Entry<V, List<E>> entry : adjacency.entrySet()){
        if(entry.getValue().size() == 1){
            start = entry.getKey();
            break;
        }
    }
    if(start == null && !adjacency.isEmpty()){
        start = adjacency.keySet().iterator().next();
    }

    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    double weight = 0.0;

    if(start != null){
        vertexList.add(start);
        V current = start;
        E prevEdge = null;
        while(edgeList.size() < tour.size()){
            List<E> edgesAt = adjacency.get(current);
            if(edgesAt == null || edgesAt.isEmpty()){
                break;
            }
            E nextEdge = null;
            for(E e : edgesAt){
                if(prevEdge == null || !e.equals(prevEdge)){
                    nextEdge = e;
                    break;
                }
            }
            if(nextEdge == null){
                break;
            }
            edgeList.add(nextEdge);
            weight += graph.getEdgeWeight(nextEdge);
            V next = graph.getEdgeSource(nextEdge).equals(current)
                     ? graph.getEdgeTarget(nextEdge)
                     : graph.getEdgeSource(nextEdge);
            current = next;
            vertexList.add(current);
            prevEdge = nextEdge;
        }
    }

    return new GraphPath<V,E>() {
        @Override public Graph<V,E> getGraph(){ return graph; }
        @Override public List<V> getVertexList(){ return vertexList; }
        @Override public List<E> getEdgeList(){ return edgeList; }
        @Override public double getWeight(){ return weight; }
    };
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // trivial case
    if (tour == null || tour.isEmpty()) {
        return new DefaultGraphPath<>(graph,
                Collections.emptyList(),
                Collections.emptyList());
    }

    // Build adjacency map vertex -> list of incident edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }

    // Find a start vertex: vertex of degree 1 (path) or any vertex (cycle)
    V start = null;
    for (Map.Entry<V, List<E>> kv : adjacency.entrySet()) {
        if (kv.getValue().size() == 1) {
            start = kv.getKey();
            break;
        }
    }

    if (start == null) {
        // Tree is a cycle: pick an arbitrary vertex
        start = adjacency.keySet().iterator().next();
    }

    // Order the tour
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    V current = start;
    V previous = null;

    while (true) {
        vertices.add(current);
        List<E> incident = adjacency.get(current);
        if (incident == null || incident.isEmpty()) {
            break;
        }

        boolean moved = false;
        for (E e : incident) {
            if (!remaining.contains(e)) {
                continue;
            }
            V neighbour = graph.getEdgeSource(e).equals(current)
                    ? graph.getEdgeTarget(e)
                    : graph.getEdgeSource(e);
            if (neighbour.equals(previous)) {
                continue; // avoid backtracking
            }
            // progress to neighbour
            edges.add(e);
            remaining.remove(e);
            previous = current;
            current = neighbour;
            moved = true;
            break;
        }

        if (!moved) {
            break; // no further edges from current vertex
        }

        if (current.equals(start) && remaining.isEmpty()) {
            break; // completed a cycle
        }
    }

    // If path (not closed), append the last vertex
    if (!current.equals(start) && !remaining.isEmpty() && remaining.isEmpty() == false) {
        vertices.add(current);
    }

    return new DefaultGraphPath<>(graph, vertices, edges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour==null || tour.isEmpty()){
        return null;
    }
    // Build adjacency mapping for vertices to the edges in the tour
    Map<V, List<E>> adj = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adj.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adj.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }

    // Pick an arbitrary starting edge
    Iterator<E> iter = tour.iterator();
    if (!iter.hasNext()) {
        return null;
    }
    E startEdge = iter.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = graph.getEdgeTarget(startEdge);

    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> used = new HashSet<>();

    vertices.add(startVertex);
    vertices.add(currentVertex);
    edges.add(startEdge);
    used.add(startEdge);

    while (true) {
        List<E> adjEdges = adj.getOrDefault(currentVertex, Collections.emptyList());
        E nextEdge = null;
        for (E e : adjEdges) {
            if (!used.contains(e)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            // No unused adjacent edge found: we might be back at the start
            if (currentVertex.equals(startVertex)) {
                break;
            } else {
                // Incomplete tour
                return null;
            }
        }

        edges.add(nextEdge);
        used.add(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(currentVertex)
                ? graph.getEdgeTarget(nextEdge)
                : graph.getEdgeSource(nextEdge);
        vertices.add(nextVertex);
        currentVertex = nextVertex;

        if (currentVertex.equals(startVertex)) {
            break;
        }
    }

    // Ensure the path is closed if needed
    if (!vertices.get(0).equals(vertices.get(vertices.size() - 1))) {
        vertices.add(vertices.get(0));
    }

    // Construct and return the GraphPath
    return new org.jgrapht.GraphPathImpl<>(graph, vertices, edges, false, 0.0);
}

