        if(entry instanceof ConstantNameAndTypeInfo){
            ConstantNameAndTypeInfo ci = (ConstantNameAndTypeInfo) entry;
            if(ci.getName().equals(name) && ci.getDescriptor().equals(descriptor)){
                // Found a duplicate, return its index
                return i;
