    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }
    // Ensure the zero bucket exists
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new java.util.HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }
    java.util.Iterator<Integer> it = minBucket.iterator();
    while (it.hasNext()) {
        int v = it.next();
        labels.set(v, 0);
        zeroBucket.add(v);
        it.remove(); // remove from minBucket
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // If the bucket list is empty or the specified label is out of bounds, nothing to do.
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    // If the bucket is already empty, no action is required.
    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }

    // Ensure the zero bucket exists; create it if it is null.
    if (bucketsByLabel.size() <= 0) {
        // If the list itself is missing bucket 0, this is an error state; just return.
        return;
    }
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }

    // Move each vertex from the min bucket to bucket 0 and update its label.
    for (Integer v : minBucket) {
        zeroBucket.add(v);
        // Update the label in the labels list. If the list is not large enough, ignore.
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }

    // Clear the min bucket after moving its contents.
    minBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Guard against invalid input or when the minimum label is already 0.
    if (minLabel <= 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }

    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source.isEmpty()) {
        return;
    }

    Set<Integer> target = bucketsByLabel.get(0);
    Iterator<Integer> it = source.iterator();
    while (it.hasNext()) {
        int v = it.next();
        it.remove();           // remove from the source bucket
        target.add(v);         // add to bucket 0
        labels.set(v, 0);      // update the vertex label
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        dest = new java.util.HashSet<>();
        bucketsByLabel.set(0, dest);
    }
    for (int v : source) {
        labels.set(v, 0);
        dest.add(v);
    }
    source.clear();
}

