private boolean unlink(ListNodeImpl<E> node){
    if (node == null){
        return false;
    }
    // Get the node's neighbours
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;
    // Unlink from previous node
    if (prev != null){
        prev.next = next;
    } else { // node is the head
        head = next;
    }
    // Unlink from next node
    if (next != null){
        next.prev = prev;
    } else { // node is the tail
        tail = prev;
    }
    // Help GC
    node.prev = null;
    node.next = null;
    // Update size
    size--;
    return true;
}

