}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // If the node is not part of any list, nothing to unlink.
    if (node.list == null) {
        return false;
    }

    // Update the mod count if the list maintains it.
    if (node.list instanceof ModCountInterface) {
        ((ModCountInterface) node.list).incrementModCount();
    }

    // Remove the node from the doubly‑linked chain.
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev != null) {
        prev.next = next;
    }
    if (next != null) {
        next.prev = prev;
    }

    // Update head or tail references if the list tracks them.
    if (node.list.head == node) {
        node.list.head = next;
    }
    if (node.list.tail == node) {
        node.list.tail = prev;
    }

    // Decrement the size counter.
    node.list.size--;

    // Disconnect the node from the list to aid garbage collection.
    node.prev = null;
    node.next = null;
    node.list = null;

    return true;
}

