public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }

    // Find last file separator (both Unix and Windows)
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find last dot in the path
    int dotIndex = path.lastIndexOf('.');

    // No dot or dot is part of a directory name (or at the start of the file name)
    if (dotIndex == -1 || dotIndex <= lastSeparator || dotIndex == path.length() - 1) {
        return path;
    }

    return path.substring(0, dotIndex);
}

