    List<Integer> suffix = new ArrayList<>(n);
    for(int i = 0; i < n; i++){
        suffix.add(0);
    }
    long sum = 0;
    for(int i = n - 1; i >= 0; i--){
        sum += bounds.get(i);
        suffix.set(i, (int)sum);
    }
    return new Pair<>(suffix, sum);
}

