    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0;
    long suffixAcc = 0;
    // Compute suffix sums from the end
    for (int i = n - 1; i >= 0; i--) {
        suffixAcc += bounds.get(i);
        suffix.add(0, (int) suffixAcc); // prepend to maintain original order
    }
    total = suffixAcc;
    return new Pair<>(suffix, total);
}

