public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array must not be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range specified");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array is null");
    }
    int len = arr.length;
    if (from < 0 || to >= len || from > to) {
        throw new IndexOutOfBoundsException(
            "Invalid range: from=" + from + ", to=" + to + ", array length=" + len);
    }
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

public static final <V> void reverse(V[] arr,int from,int to){
    if (arr == null) return;
    int n = arr.length;
    if (from < 0) from = 0;
    if (to >= n) to = n - 1;
    if (from >= to) return;
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        return;
    }
    // Adjust bounds to be within the array
    if (from < 0) {
        from = 0;
    }
    if (to >= arr.length) {
        to = arr.length - 1;
    }
    // No-op if range is invalid or trivial
    if (from >= to) {
        return;
    }
    while (from < to) {
        V tmp = arr[from];
        arr[from] = arr[to];
        arr[to] = tmp;
        from++;
        to--;
    }
}

