    // We assume the list exposes its head node; otherwise use the appropriate accessor.
    while (list.head != null) {
        // Grab the current first node
        ListNodeImpl<E> node = list.head;

        // Remove it from the source list
        list.removeListNode(node);

        // Add it to the current list
        this.addListNode(node);
