private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list.isEmpty()) return;   // nothing to move

    // Grab the first and last nodes of the source list
    ListNodeImpl<E> sourceFirst = list.header.next;
    ListNodeImpl<E> sourceLast  = list.trailer.prev;

    // Attach the source chain to the end of this list
    this.tail.next = sourceFirst;
    sourceFirst.prev = this.tail;

    // Connect the source last node to this list’s trailer
    sourceLast.next = this.trailer;
    this.trailer.prev = sourceLast;

    // Update this list’s tail pointer
    this.tail = sourceLast;

    // Leave the source list empty
    list.header.next = list.trailer;
    list.trailer.prev = list.header;
    list.size = 0;
}

