    if (str == null) {
        return prefix == null;
    }
    if (prefix == null) {
        return false;
    }
    if (str.length() < prefix.length()) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase){
    // True if both are null
    if (str == null && prefix == null) {
        return true;
    }
    // If either is null (but not both), it's false
    if (str == null || prefix == null) {
        return false;
    }
    // Prefix longer than the string cannot match
    if (prefix.length() > str.length()) {
        return false;
    }
    // Perform the check, respecting ignoreCase flag
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) {
        return prefix == null;
    }
    if (prefix == null) {
        return false;
    }
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // A non-null string cannot start with a null prefix
    if (prefix == null) {
        return false;
    }
    // If the prefix is longer than the string, cannot start with it
    if (prefix.length() > str.length()) {
        return false;
    }
    // Use String.regionMatches to respect the ignoreCase flag
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

