public void putAllWriteable(BeanMap map){
    if (map == null) throw new NullPointerException("map");
    for (Object key : map.keySet()){
        if (!this.isWritable(key)) continue;
        if (!map.isReadable(key)) continue;
        Object value = map.get(key);
        this.set(key, value);
    }
}

