    if (map == null) {
        return;
    }
    for (Object keyObj : map.keySet()) {
        if (keyObj == null) {
            continue;
        }
        String key = keyObj.toString();
        Object value;
        try {
            value = map.get(key);
        } catch (Exception e) {
            // Skip property that cannot be read (read‑only or inaccessible)
            continue;
        }
        try {
            this.put(key, value);
