public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    for (Object key : map.keySet()) {
        if (!(key instanceof String)) {
            continue;
        }
        String property = (String) key;
        Object srcValue;
        try {
            srcValue = map.get(property);
        } catch (Exception e) {
            // Property in source is write‑only (no getter) or not accessible; ignore it.
            continue;
        }
        // Attempt to write the property to this BeanMap; ignore if this bean is read‑only on it.
        try {
            this.put(property, srcValue);
        } catch (Throwable t) {
            // Property may be read‑only or otherwise unsupported; ignore.
        }
    }
}

public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    for (Object keyObj : map.keySet()) {
        String key = (String) keyObj;
        try {
            if (!map.isReadable(key)) {
                continue;
            }
            // Only write to this BeanMap if it is writable
            if (this.isWritable(key)) {
                Object value = map.get(key);
                this.put(key, value);
            }
        } catch (Exception ignored) {
            // ignore any property that cannot be read or written
        }
    }
}

