public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }

    // Select the specified row
    table.setRowSelectionInterval(row, row);

    // Make sure the row is visible in the viewport
    java.awt.Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        pane.getViewport().scrollRectToVisible(cellRect);
    }

    // Delay the repaint to give the table time to render the new selection
    javax.swing.SwingUtilities.invokeLater(() -> table.repaint());
}

