    }

    // select the row
    table.getSelectionModel().setSelectionInterval(row, row);

    // ensure the row is visible in the table
    java.awt.Rectangle rect = table.getCellRect(row, 0, true);
    if (rect != null) {
        table.scrollRectToVisible(rect);
    }

    // scroll the scroll pane to make the rectangle visible in its viewport
    java.awt.Rectangle viewRect = pane.getViewport().getViewRect();
    if (rect != null) {
        int x = Math.max(0, rect.x);
        int y = Math.max(0, rect.y);
        // adjust if the row is partially off-screen
        if (y + rect.height > viewRect.y + viewRect.height) {
            y = y - viewRect.height + rect.height;
        }
        if (y < viewRect.y) {
            y = viewRect.y;
        }
        pane.getViewport().setViewPosition(new java.awt.Point(x, y));
    }

    // delay repaint to allow the table to finish painting the new selection
    javax.swing.SwingUtilities.invokeLater(() -> pane.repaint());
}

