public void abbreviate(final int nameStart, final StringBuffer buf){
    // Get the original content of the buffer
    String original = buf.toString();
    // If nameStart is out of bounds, nothing to do
    if (nameStart < 0 || nameStart >= original.length()) {
        return;
    }
    // Extract the substring from nameStart to the end
    String sub = original.substring(nameStart);
    // Tokenize the substring by whitespace
    java.util.StringTokenizer st = new java.util.StringTokenizer(sub);
    StringBuilder abbr = new StringBuilder();
    boolean first = true;
    while (st.hasMoreTokens()) {
        String token = st.nextToken();
        if (!token.isEmpty()) {
            if (!first) {
                abbr.append(' ');
            }
            abbr.append(token.charAt(0)).append('.');
            first = false;
        }
    }
    // Replace the part of the buffer from nameStart to the end with the abbreviation
    buf.replace(nameStart, original.length(), abbr.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    // Ensure the name field is available and valid
    if (name == null) {
        return;
    }
    int len = name.length();
    if (nameStart < 0 || nameStart > len) {
        return;
    }

    // If nameStart is at the beginning, simply append the full name
    if (nameStart == 0) {
        buf.append(name);
        return;
    }

    // Iterate through the name up to nameStart, accumulating initials
    int segStart = 0;
    for (int i = 0; i < nameStart; i++) {
        char c = name.charAt(i);
        // Consider typical separator characters; underscore is also treated as a separator
        if (c == '.' || c == '/' || c == '\\' || c == ':' || c == '_' ) {
            // If there is a segment before this separator, add its first letter
            if (segStart < i) {
                buf.append(name.charAt(segStart));
                buf.append('.');
            }
            segStart = i + 1;   // new segment starts after the separator
        }
    }
    // Handle the final segment that ends at nameStart - 1
    if (segStart < nameStart) {
        buf.append(name.charAt(segStart));
        buf.append('.');
    }

    // Append the remainder of the name from nameStart onward
    buf.append(name.substring(nameStart));
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    String name = this.name;
    if (name == null || name.isEmpty()) {
        return;
    }
    int start = nameStart < 0 ? 0 : (nameStart > name.length() ? name.length() : nameStart);
    if (start == name.length()) {
        return;
    }
    String sub = name.substring(start);
    if (sub.isEmpty()) {
        return;
    }
    String[] parts = sub.split("\\.");
    if (parts.length == 0) {
        return;
    }
    for (int i = 0; i < parts.length - 1; i++) {
        if (!parts[i].isEmpty()) {
            buf.append(parts[i].charAt(0)).append('.');
        }
    }
    buf.append(parts[parts.length - 1]);
}

