    if (buf == null) {
        return;
    }
    // Assume the full name is stored in a field accessible via getName().
    String fullName = getName();
    if (fullName == null) {
        return;
    }

    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start > fullName.length()) {
        return;
    }

    String sub = fullName.substring(start).trim();
    if (sub.isEmpty()) {
        return;
    }

    String[] parts = sub.split("\\s+");
    for (int i = 0; i < parts.length; i++) {
        String part = parts[i];
        if (part.isEmpty()) {
            continue;
        }
        if (i < parts.length - 1) {
            buf.append(Character.toUpperCase(part.charAt(0))).append('.');
        } else {
            buf.append(part);
        }
        if (i < parts.length - 1) {
            buf.append(' ');
        }
    }
}

