    if (buf == null || nameStart < 0) {
        return;
    }
    String full = buf.toString();
    if (nameStart >= full.length()) {
        return;
    }
    StringBuilder abbr = new StringBuilder();
    boolean nextChar = true;
    for (int i = nameStart; i < full.length(); i++) {
        char c = full.charAt(i);
        if (c == '.' || c == '/' || c == '-') {
            // Preserve separators to maintain the structure
            abbr.append(c);
            nextChar = true;
        } else if (nextChar) {
            // Append the first character of each segment
            abbr.append(c);
            nextChar = false;
        }
    }
    buf.append(abbr);
}

