private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) continue;
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V vi = (V) arr[i];
        for (int j = i + 1; j < size; j++) {
            V vj = (V) arr[j];
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices == null || vertices.size() <= 1) {
        return true;
    }
    List<V> verts = new ArrayList<>(vertices);
    int n = verts.size();
    for (int i = 0; i < n; i++) {
        V u = verts.get(i);
        for (int j = i + 1; j < n; j++) {
            V v = verts.get(j);
            if (!graph.containsEdge(u, v)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    java.util.List<V> vertexList = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = vertexList.get(j);
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // An empty set or a single vertex is trivially a clique.
    if (vertices == null || vertices.size() <= 1) {
        return vertices != null; // null set considered non‑clique.
    }

    // Ensure all specified vertices are part of the graph.
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }
    }

    // Convert to a list to allow index-based pair checks.
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();

    // Check adjacency of every unordered pair of vertices.
    for (int i = 0; i < n; i++) {
        V vi = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = vertexList.get(j);
            // For undirected graphs graph.containsEdge(u, v) should return true
            // if there is an edge regardless of direction. If the graph is
            // directed and a bidirectional clique is required, 
            // both directions would have to be checked here.
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    for (K key : keys) {
        if (!(key instanceof Number)) {
            bounds.add(null);
            continue;
        }
        int target = ((Number) key).intValue();
        int best = Integer.MIN_VALUE;
        for (K candidate : keys) {
            if (candidate instanceof Number) {
                int val = ((Number) candidate).intValue();
                if (val <= target && val > best) {
                    best = val;
                }
            }
        }
        bounds.add(best);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        @SuppressWarnings("unchecked")
        Integer current = (Integer) keys.get(i);
        Integer maxLower = null;
        for (int j = 0; j < keys.size(); j++) {
            if (i == j) continue;
            @SuppressWarnings("unchecked")
            Integer candidate = (Integer) keys.get(j);
            if (candidate != null && candidate < current) {
                if (maxLower == null || candidate > maxLower) {
                    maxLower = candidate;
                }
            }
        }
        // If no lower key exists, you can decide on a sentinel value, e.g., Integer.MIN_VALUE
        lowerBounds.add(maxLower != null ? maxLower : Integer.MIN_VALUE);
    }
    return lowerBounds;
}

private java.util.List<Integer> computeLowerBounds(java.util.List<Integer> keys){
    java.util.List<Integer> sorted = new java.util.ArrayList<>(keys);
    java.util.Collections.sort(sorted);
    java.util.List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (Integer key : keys){
        int idx = java.util.Collections.binarySearch(sorted, key);
        if (idx < 0){
            idx = -idx - 1 - 1;
        }
        if (idx >= 0){
            bounds.add(sorted.get(idx));
        } else {
            bounds.add(null);
        }
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    // Assume the keys are integers (K can be cast to Integer). This method
    // returns a list where each entry i contains the maximum key value that is
    // strictly less than keys.get(i). If there is no such key, Integer.MIN_VALUE
    // is used to indicate the absence of a lower bound.
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }

    // Convert the list to a list of integers for easier comparison.
    List<Integer> intKeys = new ArrayList<>(keys.size());
    for (K k : keys) {
        intKeys.add((Integer) k);
    }

    for (int i = 0; i < intKeys.size(); i++) {
        int current = intKeys.get(i);
        int maxLower = Integer.MIN_VALUE;
        for (int j = 0; j < intKeys.size(); j++) {
            if (i == j) {
                continue;
            }
            int candidate = intKeys.get(j);
            if (candidate < current && candidate > maxLower) {
                maxLower = candidate;
            }
        }
        lowerBounds.add(maxLower);
    }

    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    // Make a sorted copy of the keys.
    List<K> sorted = new ArrayList<>(keys);
    //noinspection unchecked
    Collections.sort((List<? super K>) sorted, (a, b) -> {
        Comparable<? super K> ca = (Comparable<? super K>) a;
        return ca.compareTo(b);
    });

    for (K key : keys) {
        // Binary search for the key in the sorted list.
        int idx = Collections.binarySearch(sorted, key, (a, b) -> {
            Comparable<? super K> ca = (Comparable<? super K>) a;
            return ca.compareTo(b);
        });

        if (idx >= 0) {
            // Exact match: the maximum lower bound is at the same index.
            bounds.add(idx);
        } else {
            // No exact match: insertion point is -(idx) - 1.
            int insertionPoint = -idx - 1;
            int lowerIdx = insertionPoint - 1;
            bounds.add(lowerIdx);
        }
    }
    return bounds;
}

private void pop(final String descriptor) {
    // The stack that holds the output frame values.
    // It is assumed to have a pop() method that removes the top value.
    // (e.g., java.util.Stack<AbstractType> stack)
    int i = 0;
    int len = descriptor.length();

    if (len == 0) {
        return; // nothing to pop
    }

    // If the descriptor is a method descriptor, we only pop its argument types.
    if (descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        while (i < len) {
            char ch = descriptor.charAt(i);
            if (ch == ')') {
                // end of argument list, ignore return type
                break;
            }
            // skip one argument descriptor
            if (ch == '[') {
                // Skip all '[' array-indicators
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                // Now at component type
                if (i < len && descriptor.charAt(i) == 'L') {
                    // Object type: skip until ';'
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    // Primitive type: skip single char
                    i++;
                }
            } else if (ch == 'L') {
                // Object type: skip until ';'
                i = descriptor.indexOf(';', i) + 1;
            } else {
                // Primitive type: skip single char
                i++;
            }
            // Pop one value from the stack for this argument type
            stack.pop();
        }
        // No further action: method return type is ignored
        return;
    }

    // Descriptor is a single type (not a method)
    // Skip the type descriptor
    ch = descriptor.charAt(i);
    if (ch == '[') {
        while (i < len && descriptor.charAt(i) == '[') {
            i++;
        }
        if (i < len && descriptor.charAt(i) == 'L') {
            i = descriptor.indexOf(';', i) + 1;
        } else {
            i++;
        }
    } else if (ch == 'L') {
        i = descriptor.indexOf(';', i) + 1;
    } else {
        i++;
    }
    // Pop the value represented by this type
    stack.pop();
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("invalid descriptor: " + descriptor);
        }
        String args = descriptor.substring(1, end);
        int pos = 0;
        while (pos < args.length()) {
            pos = popType(args, pos);
        }
    } else {
        popType(descriptor, 0);
    }
}

private int popType(String s, int pos) {
    // Skip array dimensions
    while (pos < s.length() && s.charAt(pos) == '[') {
        pos++;
    }
    if (pos >= s.length()) {
        throw new IllegalArgumentException("invalid descriptor: " + s);
    }
    char c = s.charAt(pos);
    switch (c) {
        case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
            outputStack.pop();
            return pos + 1;
        case 'J': case 'D':
            outputStack.pop();
            outputStack.pop(); // JVM long/double occupy two slots
            return pos + 1;
        case 'L':
            int end = s.indexOf(';', pos);
            if (end == -1) {
                throw new IllegalArgumentException("invalid descriptor: " + s);
            }
            outputStack.pop();
            return end + 1;
        default:
            throw new IllegalArgumentException("unknown type descriptor: " + c);
    }
}

private void pop(final String descriptor){
    // Determine if descriptor is a method descriptor
    final boolean isMethod = descriptor.length() > 0 && descriptor.charAt(0) == '(';
    int index = isMethod ? 1 : 0; // start after '(' for method descriptors

    // Collect slot counts for each type to pop
    final ArrayList<Integer> slots = new ArrayList<>();

    while(index < descriptor.length()){
        // For method descriptor, stop at ')'
        if(isMethod && descriptor.charAt(index) == ')'){
            break;
        }
        char c = descriptor.charAt(index);
        switch(c){
            case 'J': // long
            case 'D': // double: two slots
                slots.add(2);
                index++;
                break;
            case '[': // array – skip whole array description
                // consume all '[' characters
                while(descriptor.charAt(index) == '['){
                    index++;
                }
                // now at base type
                if(descriptor.charAt(index) == 'L'){
                    // object array: consume until ';'
                    while(descriptor.charAt(index) != ';'){
                        index++;
                    }
                    index++; // skip ';'
                }else{
                    // primitive array; consume base type
                    index++;
                }
                slots.add(1);
                break;
            case 'L': // object
                // consume until ';'
                while(descriptor.charAt(index) != ';'){
                    index++;
                }
                index++; // skip ';'
                slots.add(1);
                break;
            default: // primitive types (B, C, D, F, I, S, Z)
                slots.add(1);
                index++;
                break;
        }
    }

    // Pop the required number of slots from output frame stack
    for(int slot : slots){
        // For long and double we pop twice (already accounted by slot count)
        for(int i=0;i<slot;i++){
            outputFrameStack.pop();
        }
    }
}

private void pop(final String descriptor) {
    int slotsToPop = 0;
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i++);
            switch (c) {
                case '[':
                    // skip any additional '[' characters that represent array dimensions
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i++;
                    }
                    // the element type follows; one slot for the array reference
                    if (i < descriptor.length()) {
                        char elem = descriptor.charAt(i);
                        if (elem == 'J' || elem == 'D') {
                            // element is long or double, but array occupies one slot only
                            i++;
                        } else if (elem == 'L') {
                            // object type: skip until ';'
                            while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                                i++;
                            }
                            i++; // skip ';'
                        } else {
                            // primitive, just consume the single character
                            i++;
                        }
                    }
                    slotsToPop += 1;
                    break;
                case 'L':
                    // object reference: skip until ';'
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                    slotsToPop += 1;
                    break;
                case 'J':
                case 'D':
                    slotsToPop += 2; // long and double take two slots
                    break;
                case 'V':
                    // void type, not a stack slot
                    break;
                default:
                    // primitive type: byte, char, double, float, int, long, short, boolean
                    // double and long were handled, the rest take one slot
                    // all other primitive descriptors are single slot
                    slotsToPop += 1;
                    break;
            }
        }
        // return type after ')', not popped
    } else {
        // single type descriptor (not a method descriptor)
        if (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            switch (c) {
                case '[':
                    // skip array dimensions
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i++;
                    }
                    // skip element type
                    if (i < descriptor.length()) {
                        char elem = descriptor.charAt(i);
                        if (elem == 'L') {
                            while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                                i++;
                            }
                            i++; // skip ';'
                        } else {
                            i++; // skip primitive type
                        }
                    }
                    slotsToPop += 1;
                    break;
                case 'L':
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                    slotsToPop += 1;
                    break;
                case 'J':
                case 'D':
                    slotsToPop += 2;
                    break;
                case 'V':
                    // void, no slot
                    break;
                default:
                    slotsToPop += 1;
                    break;
            }
        }
    }

    for (int s = 0; s < slotsToPop; s++) {
        output.pop(); // assumes a field named 'output' of a stack type
    }
}

