private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new java.util.ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return bounds;
    }
    // Check if keys are actually Integer objects
    if (!(keys.get(0) instanceof Integer)){
        for (int i = 0; i < keys.size(); i++){
            bounds.add(0);
        }
        return bounds;
    }
    java.util.List<Integer> sorted = new java.util.ArrayList<>(keys.size());
    for (K k : keys){
        sorted.add((Integer)k);
    }
    java.util.Collections.sort(sorted);
    for (K k : keys){
        int val = (Integer)k;
        int idx = java.util.Collections.binarySearch(sorted, val);
        if (idx < 0){
            idx = -idx - 1;
        }
        int upper;
        if (idx >= sorted.size() - 1){
            upper = sorted.get(sorted.size() - 1);
        } else {
            upper = sorted.get(idx + 1);
        }
        bounds.add(upper);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys) {
    java.util.List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    int bound = keys.size();
    for (K key : keys) {
        bounds.add(bound);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    List<Integer> sorted = new ArrayList<>();
    for (K k : keys){
        sorted.add((Integer)k);
    }
    Collections.sort(sorted);
    for (Integer key : sorted){
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0){
            idx = -(idx + 1);
        } else {
            // If duplicates, move to the first occurrence to ensure we get the next distinct element
            while (idx > 0 && sorted.get(idx - 1).equals(key)){
                idx--;
            }
        }
        int upperIdx = idx + 1;
        if (upperIdx < sorted.size()){
            bounds.add(sorted.get(upperIdx));
        } else {
            bounds.add(null); // no upper bound for the largest element
        }
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null || keys.isEmpty()){
        return new java.util.ArrayList<>();
    }
    int maxVal = Integer.MIN_VALUE;
    for (K key : keys){
        if (key instanceof Number){
            int value = ((Number)key).intValue();
            if (value > maxVal){
                maxVal = value;
            }
        }
    }
    if (maxVal == Integer.MIN_VALUE){
        maxVal = Integer.MAX_VALUE;
    }
    java.util.List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++){
        bounds.add(maxVal);
    }
    return bounds;
}

