public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath == null ? "" : relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    boolean isAbsolute = path.startsWith("/");
    // Build base parts from the given path (excluding the last component if it's a file)
    String[] pathTokens = path.split("/");
    int limit = pathTokens.length;
    if (!path.endsWith("/") && limit > 0) {
        limit--; // drop the last token (assumed to be a file)
    }
    java.util.List<String> parts = new java.util.ArrayList<>();
    for (int i = 0; i < limit; i++) {
        String token = pathTokens[i];
        if (token.isEmpty() || token.equals(".")) {
            continue;
        }
        parts.add(token);
    }
    // Process the relative path components
    for (String seg : relativePath.split("/")) {
        if (seg.isEmpty() || seg.equals(".")) {
            // skip
        } else if (seg.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            } else if (!isAbsolute) {
                // For relative paths that go above the initial location,
                // keep the ".." component to reflect that navigation.
                parts.add("..");
            }
        } else {
            parts.add(seg);
        }
    }
    // Assemble the final path
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    for (int i = 0; i < parts.size(); i++) {
        sb.append(parts.get(i));
        if (i < parts.size() - 1) {
            sb.append("/");
        }
    }
    String result = sb.toString();
    if (result.isEmpty() && isAbsolute) {
        result = "/";
    }
    return result;
}

public static String applyRelativePath(String path, String relativePath){
    if (path == null || relativePath == null) {
        return null;
    }
    try {
        java.io.File file = new java.io.File(path, relativePath);
        // Resolve relative path and normalize the path
        String canonical = file.getCanonicalPath().replace("\\", "/");
        return canonical;
    } catch (java.io.IOException e) {
        // Fallback: manually resolve and normalize
        String combined = path.endsWith("/") || relativePath.startsWith("/")
                ? path + relativePath
                : path + "/" + relativePath;
        java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
        for (String part : combined.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.add(part);
            }
        }
        StringBuilder result = new StringBuilder();
        if (combined.startsWith("/")) {
            result.append("/");
        }
        java.util.Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            result.append(it.next());
            if (it.hasNext()) {
                result.append("/");
            }
        }
        return result.length() == 0 ? "." : result.toString();
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Ensure path ends with '/' if it's a directory; otherwise strip file name
    String combined = path;
    if (!combined.endsWith("/")) {
        int lastSlash = combined.lastIndexOf('/');
        if (lastSlash >= 0) {
            combined = combined.substring(0, lastSlash + 1);
        } else {
            combined = "";
        }
    }
    combined += relativePath;

    boolean leadingSlash = combined.startsWith("/");
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().equals("..")) {
                stack.removeLast();
            } else if (!leadingSlash) {
                stack.addLast("..");
            }
        } else {
            stack.addLast(part);
        }
    }

    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }
    String res = result.toString();
    // If we ended up with an empty string but the original path was absolute, return "/"
    if (res.isEmpty() && leadingSlash) {
        return "/";
    }
    return res;
}

public static String applyRelativePath(String path,String relativePath){
    boolean isAbsolute = path.startsWith("/");
    java.util.List<String> parts = new java.util.ArrayList<>();
    for (String seg : path.split("/")) {
        if (seg.isEmpty() || seg.equals(".")) continue;
        parts.add(seg);
    }
    for (String seg : relativePath.split("/")) {
        if (seg.isEmpty() || seg.equals(".")) continue;
        if (seg.equals("..")) {
            if (!parts.isEmpty()) parts.remove(parts.size() - 1);
        } else {
            parts.add(seg);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) sb.append("/");
    for (int i = 0; i < parts.size(); i++) {
        if (i > 0) sb.append("/");
        sb.append(parts.get(i));
    }
    return sb.toString();
}

