static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return new String[0];
    }
    int count = 0;
    for (Object o : array) {
        if (o != null) {
            count++;
        }
    }
    if (count == array.length) {
        // All elements are non-null; cast to String[] safely
        return (String[]) array;
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

static String[] toNoNullStringArray(Object[] array){
    if (array == null || array.length == 0) {
        return new String[0];
    }
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        try {
            return (String[]) array;
        } catch (ClassCastException e) {
            // fall through to rebuild array
        }
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            if (obj instanceof String) {
                result[idx++] = (String) obj;
            } else {
                result[idx++] = obj.toString();
            }
        }
    }
    return result;
}

