static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return null;
    }
    int len = array.length;
    boolean hasNull = false;
    for (int i = 0; i < len; i++) {
        if (array[i] == null) {
            hasNull = true;
            break;
        }
    }
    if (!hasNull) {
        return (String[]) array;
    }
    int count = 0;
    for (int i = 0; i < len; i++) {
        if (array[i] != null) {
            count++;
        }
    }
    String[] result = new String[count];
    int idx = 0;
    for (int i = 0; i < len; i++) {
        Object e = array[i];
        if (e != null) {
            result[idx++] = (String) e;
        }
    }
    return result;
}

static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    // First pass: copy non‑null elements into a temporary array
    String[] temp = new String[array.length];
    int count = 0;
    for (Object o : array) {
        if (o != null) {
            // we are expecting the element to be a String
            temp[count++] = (String) o;
        }
    }
    // If no nulls were found, return the temp array as is (grown size is the same)
    if (count == temp.length) {
        return temp;
    }
    // Otherwise shrink to the actual number of non‑null elements
    String[] result = new String[count];
    System.arraycopy(temp, 0, result, 0, count);
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSepUnix = filename.lastIndexOf('/');
    int lastSepWindows = filename.lastIndexOf('\\');
    int lastSep = Math.max(lastSepUnix, lastSepWindows);
    if (lastSep > lastDot) {
        return -1;
    }
    return lastDot;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
