protected void append(LoggingEvent event) {
    // Retrieve the formatted message to send
    String message = event.getFormattedMessage();

    // Iterate over all connected clients and send the message
    for (Object clientObj : this.connectedClients) {
        try {
            // Assuming each client has a method send(String msg)
            Method sendMethod = clientObj.getClass().getMethod("send", String.class);
            sendMethod.invoke(clientObj, message);
        } catch (Exception ex) {
            // Log or ignore any exception while sending to a client
            // e.g., print to console or use a logger if available
        }
    }
}

protected void append(LoggingEvent event) {
    // Render the event using the appender's layout if present, otherwise use the message directly.
    String formatted = (layout != null) ? layout.doLayout(event) : event.getRenderedMessage();

    // Broadcast the formatted message to every connected client.
    for (PrintWriter writer : writers) {
        try {
            writer.println(formatted);
            writer.flush();
        } catch (Exception ignored) {
            // If a client has disconnected or an error occurs, ignore it.
        }
    }
}

protected void append(LoggingEvent event) {
    // get the rendered log message
    String msg = event.getRenderedMessage();
    // send the message to every connected client
    for (ClientHandler client : connectedClients) {
        try {
            client.write(msg);
        } catch (Exception e) {
            // If sending to a client fails, we can ignore it or handle the exception
            // for example: log the error or remove the client from the list
        }
    }
}

protected void append(LoggingEvent event){
    // Format the log message using the appender's layout if available,
    // otherwise just use the rendered message.
    String message = (this.getLayout() != null) ? this.getLayout().format(event) : event.getRenderedMessage();

    // Broadcast the message to all currently connected clients.
    // It is assumed that the appender maintains a collection called
    // 'connectedClients' that holds Socket objects representing each client.
    for (java.net.Socket client : this.connectedClients) {
        try {
            java.io.OutputStream out = client.getOutputStream();
            out.write(message.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            out.flush();
        } catch (java.io.IOException e) {
            // If sending to a client fails, ignore the exception or log it
            // according to the appender's error handling strategy.
        }
    }
}

protected void append(LoggingEvent event){
    // Format the log message.  The LoggingEvent interface provides a rendered message
    // which already contains any formatting that was applied by the logger.
    String message = event.getRenderedMessage();
    if (message == null) {
        return;
    }

    // Iterate over all currently connected clients and send the message.
    // The collection of clients is assumed to be a field of this appender.
    // Each client is expected to expose a write(String) method that sends
    // the message across the connection.
    for (Client client : clients) {
        try {
            client.write(message);
        } catch (Exception e) {
            // If a client connection fails, ignore the exception so that
            // the remaining clients continue to receive the log event.
            // In a real implementation you might want to log this error
            // or remove the client from the collection.
        }
    }
}

