private void checkIfPackedField() throws IOException {
    // Determine the field number and wire type from the current tag.
    int fieldNumber = (tag >>> 3);
    int wireType = tag & 0x7;

    // Look up the descriptor for this field.
    FieldDescriptor field = descriptor.findFieldByNumber(fieldNumber);
    if (field == null) {
        // No descriptor - nothing to do.
        return;
    }

    // Detect a packed repeated field, which is represented as a length‑delimited
    // wire type (wire type 2).  If the field is repeated and marked as packed
    // we prepare to read a packed block by setting up a sub‑limit.
    if (wireType == WireFormatLite.WIRETYPE_LENGTH_DELIMITED
            && field.isRepeated()
            && field.isPacked()) {
        // Read the packed block length.
        int packedLength = input.readRawVarint32();

        // Push a new limit for the packed block and remember the previous limit.
        oldLimit = input.pushLimit(packedLength);

        // Mark that subsequent reads should treat this as a packed field.
        currentPackedField = field;
        isReadingPacked = true;
    }
}

