    // internal state to reflect that we are now reading packed data.
    if (wireType == WireFormat.WIRETYPE_LENGTH_DELIMITED) {
        // Switch the parser into packed‑field mode.
        readingPacked = true;
        // Consume the length prefix that tells how many bytes are packed.
        int packedLength = readRawVarint32();
        // Remember the byte position at which the packed field ends,
        // so that subsequent reads can respect this boundary.
        packedFieldEnd = getTotalBytesRead() + packedLength;
    }
}

private void checkIfPackedField() throws IOException {
    // In protobuf, a packed repeated field is encoded using the length‑delimited wire
    // type (value 2) combined with the field option `packed = true`.  The parser
    // keeps track of the last field descriptor (`currentField`) and the wire
    // type that was just read (`currentWireType`).  When we encounter a tag that
    // refers to the same field number as an already‑parsed packed field, we set
    // a flag (`packedFieldMode`) so that subsequent reads of values are handled
    // as the raw bytes of a packed list.
    if (currentWireType == 2 && currentField != null && currentField.isPacked()) {
        packedFieldMode = true;
    } else {
        packedFieldMode = false;
    }
}

private void checkIfPackedField() throws IOException {
    // In the protocol buffer format, repeated primitive fields may be encoded in
    // a packed format.  Then the field is represented as a single length‑delimited
    // blob containing the concatenation of the encoded values.  The parser must
    // detect this situation and set its internal state so that subsequent reads
    // will treat the following bytes as a packed field.
    //
    // The current tag that was just read is in 'currentTag'.  We only consider
    // blobs that use the length‑delimited wire type.  The descriptor of the
    // field being processed is stored in 'lastField' (for example a
    // GeneratedMessageLite.FieldAccessorTable.FieldAccessor).  The descriptor
    // exposes whether the field is repeated and whether it is declared as
    // packed.  When all these conditions hold, we set the 'packed' flag.
    //
    // This flag is later used by read*Value() methods to correctly read a
    // packed block.
    if ((currentTag & 0x7) == WireFormat.WIRETYPE_LENGTH_DELIMITED &&
        lastField != null &&
        lastField.isRepeated() &&
        lastField.isPacked()) {
        packed = true;
    } else {
        packed = false;
    }
}

