    // Identifies a packed repeated field by looking at the wire type.
    // If the current tag indicates a length-delimited field and the
    // descriptor marks this field as packed, set the packed flag,
    // read the length of the packed segment and push a new limit.
    if ((this.tag & 0x7) == WireFormat.WIRETYPE_LENGTH_DELIMITED &&
        this.fieldDescriptor != null && this.fieldDescriptor.isPacked()) {
        this.isPacked = true;
        int packedLength = readRawVarint32();
        this.oldLimit = pushLimit(packedLength);
    }
}

