public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = in.read();
        if (b == -1) {
            // End of stream encountered before a full tag was read.
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            // Successful read of variable-length integer.
            return result;
        }
        shift += 7;
    }
    // If we got here the tag was too long to fit in 32 bits.
    throw new IOException("Malformed tag: varint too long");
}

