private String buildContentRange(){
    // Build a valid Content-Range header value.
    // It is assumed that the class has the following fields:
    //   long contentLength   - the total size of the resource
    //   long rangeStart      - start byte of the requested range
    //   long rangeEnd        - end byte of the requested range
    if (contentLength <= 0 || rangeStart < 0 || rangeEnd < 0) {
        return null;
    }
    return String.format("bytes %d-%d/%d", rangeStart, rangeEnd, contentLength);
}

private String buildContentRange() {
    // Assuming there are instance fields: startOffset, endOffset, and totalSize
    return String.format("bytes %d-%d/%d", this.startOffset, this.endOffset, this.totalSize);
}

private String buildContentRange() {
    // Build a standard HTTP Content-Range header value.
    // Assumes that the following instance fields are defined elsewhere in the class:
    //   long startByte;        // the first byte index of the returned data
    //   long endByte;          // the last byte index of the returned data (inclusive)
    //   long contentLength;    // the total size of the resource being ranged
    if (this.startByte < 0 || this.endByte < 0 || this.contentLength < 0) {
        throw new IllegalStateException("Content range values have not been initialized");
    }
    return "bytes " + startByte + "-" + endByte + "/" + contentLength;
}

private String buildContentRange() {
    // Validate range parameters before constructing the header.
    if (requestedStart < 0 || requestedEnd < 0 || requestedEnd < requestedStart) {
        return null; // Invalid range; caller should handle absence of the header.
    }

    StringBuilder builder = new StringBuilder(32);
    builder.append("bytes ")
           .append(requestedStart)
           .append('-')
           .append(requestedEnd)
           .append('/');

    // If the total length is unknown, "*" is used per RFC 7233.
    builder.append(contentLength >= 0 ? contentLength : "*");

    return builder.toString();
}

private String buildContentRange() {
    long start = this.startByte;
    long end = this.endByte;
    long totalLength = this.totalBytes;
    return "bytes " + start + "-" + end + "/" + totalLength;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        List<String> block = new ArrayList<>();
        String line;
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS");
        ZoneId zone = ZoneOffset.UTC;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) {
                if (!block.isEmpty()) {
                    String timestampLine = block.get(0).trim();
                    long timestamp;
                    try {
                        LocalDateTime ldt = LocalDateTime.parse(timestampLine, formatter);
                        timestamp = ldt.atZone(zone).toInstant().toEpochMilli();
                    } catch (Exception e) {
                        // if timestamp cannot be parsed, skip this block
                        block.clear();
                        continue;
                    }
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                            try {
                                ThreadSnapshot ts = ThreadSnapshot.fromLines(block);
                                result.add(ts);
                            } catch (Exception e) {
                                // if parsing the snapshot fails, ignore and continue
                            }
                            break;
                        }
                    }
                    block.clear();
                }
            } else {
                block.add(line);
            }
        }
        // handle last block if file doesn't end with blank line
        if (!block.isEmpty()) {
            String timestampLine = block.get(0).trim();
            long timestamp;
            try {
                LocalDateTime ldt = LocalDateTime.parse(timestampLine, formatter);
                timestamp = ldt.atZone(zone).toInstant().toEpochMilli();
            } catch (Exception e) {
                block.clear();
                return result;
            }
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                    try {
                        ThreadSnapshot ts = ThreadSnapshot.fromLines(block);
                        result.add(ts);
                    } catch (Exception e) {
                        // ignore parse failure
                    }
                    break;
                }
            }
            block.clear();
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> snapshots = new java.util.ArrayList<>();
    java.nio.file.Path path = file.toPath();
    java.util.List<String> lines = java.nio.file.Files.readAllLines(path, java.nio.charset.StandardCharsets.UTF_8);
    for (String line : lines) {
        if (line == null || line.trim().isEmpty()) {
            continue;
        }
        // The line format is assumed to be: <timestamp> <snapshot data>
        String[] parts = line.trim().split("\\s+", 2);
        long timestamp;
        try {
            timestamp = Long.parseLong(parts[0]);
        } catch (NumberFormatException e) {
            continue; // skip if the timestamp is malformed
        }
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            // Assumes the time range exposes getStartTime() and getEndTime() returning long
            long start = range.getStartTime();
            long end = range.getEndTime();
            if (timestamp >= start && timestamp <= end) {
                String data = parts.length > 1 ? parts[1] : "";
                // Assumes ThreadSnapshot has a constructor taking a timestamp and data string
                snapshots.add(new ThreadSnapshot(timestamp, data));
                break; // matched this range, no need to check further ranges
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Parse all snapshots from the file
    List<ThreadSnapshot> allSnapshots = parseFromFile(file);

    // If no specific time ranges are provided, return all snapshots
    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }

    // Filter snapshots that fall into any of the specified time ranges
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        long tsTime = snapshot.getTimestamp(); // assume this method exists

        for (ProfileAnalyzeTimeRange range : timeRanges) {
            long start = range.getStartTime(); // assume long timestamp
            long end = range.getEndTime();

            if (tsTime >= start && tsTime <= end) {
                filteredSnapshots.add(snapshot);
                break; // no need to check other ranges
            }
        }
    }

    return filteredSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            if (timeRanges == null || timeRanges.isEmpty()) {
                result.add(snapshot);
                continue;
            }
            long ts = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (ts >= range.getStart() && ts <= range.getEnd()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (FileInputStream fis = new FileInputStream(file);
         ObjectInputStream ois = new ObjectInputStream(fis)) {
        while (true) {
            try {
                Object obj = ois.readObject();
                if (!(obj instanceof ThreadSnapshot)) {
                    continue;
                }
                ThreadSnapshot ts = (ThreadSnapshot) obj;
                long timestamp = ts.getTimestamp(); // assuming ThreadSnapshot has getTimestamp()
                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    // assuming ProfileAnalyzeTimeRange has startTime and endTime with getters
                    if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                        inRange = true;
                        break;
                    }
                }
                if (inRange) {
                    snapshots.add(ts);
                }
            } catch (EOFException e) {
                break;
            } catch (ClassNotFoundException e) {
                throw new IOException("Failed to deserialize ThreadSnapshot from file", e);
            }
        }
    }
    return snapshots;
}
